  ["1ab93ba2"] = "Прочитайте інструкції «{item:Mor'zul's Instructions}». Призвіть істоту «{npc:Xorothian Dreadsteed}», здолайте її, а потім прив’яжіть її дух до себе.",
  ["1adc99c2"] = "Знайдіть зниклих елітних бійців Кор’крону.",
  ["1af37648"] = "Убийте боса «{npc:Morphaz}» у затонулому храмі і принесіть його кров до НІП «{npc:Greta Mosshoof}» у локації «{zone:Felwood}». Вхід до затонулого храму розташований у локації «{zone:Swamp of Sorrows}».",
  ["1b28f745"] = "Принесіть предмет із завдання до алхімічної лабораторії в підземеллі «{zone:Scholomance}». Коли з’явиться пергамент, поверніть банку до НІП «{npc:Gorzeeki Wildeyes}».",
  ["1b380a0d"] = "Вирушайте до підземелля «{zone:Blackrock Spire}» і вбийте боса «{npc:General Drakkisath}». Наберіть його крові й віднесіть її до НІП «{npc:Rexxar}».",
  ["1b5325b6"] = "Знайдіть НІП «{npc:Parqual Fintallas}» у місті «{zone:Undercity}».",
  ["1b5bf464"] = "Перше завдання цього ланцюжка.",
  ["1baf7bbd"] = "Класове завдання мисливця. Предмет «{item:Tooth of Morphaz}» випадає з боса «{npc:Morphaz}».\n\nНеобов’язкове вступне завдання:",
  ["1c6a2f47"] = "Зберіть «{item:Red Silk Bandana}»: 10 шт. з Дефіасів у підземеллі «{zone:Deadmines}».",
  ["1cf9f355"] = "Вислухайте, що скаже НІП «{npc:Tirion Fordring}».",
  ["1d2d16ff"] = "Знайдіть рубін, сапфір і топаз, розкидані по підземеллю «{zone:Uldaman}». Здобувши їх, зв’яжіться з НІП «{npc:Talvash del Kissel}» на відстані за допомогою предмета «{item:Phial of Scrying}», який він вам дав.",
  ["1d3f2996"] = "Принесіть предмет «{item:Tablet Shard}» до НІП «{npc:Kin'weelay}» у таборі «{zone:Grom'gol Base Camp}».",
  ["1d62a960"] = "Принесіть предмет «{item:Lost Thunderbrew Recipe}» до НІП «{npc:Ragnar Thunderbrew}» у місцевості «{zone:Kharanos}».",
  ["1d658bc1"] = "Ланцюжок починається на 18-му рівні із завдання «{quest:Diplomatic Incident}» від НІП «{npc:Danitha Morr}» у місцевості «{zone:Bandarion Keep}», «{zone:Tirisfal Glades}». Він веде до місцевості «{zone:Fenris Isle}», де ви звільняєте НІП «{npc:Lumina Windsinger}» з місцевості «{zone:Fenris Keep}».",
  ["1d886bba"] = "Убийте «{npc:Ragefire Trogg}»: 8 і «{npc:Ragefire Shaman}»: 8 у підземеллі «{zone:Ragefire Chasm}».",
  ["1d9e56ae"] = "Принесіть предмет «{item:Techbot's Memory Core}» до НІП «{npc:Tinkmaster Overspark}» у місті «{zone:Ironforge}».",
  ["1de0aff9"] = "Здобудьте предмет «{item:Fel Infused Blossom}» із центрального саду міста «{zone:Dalaran}».",
  ["1e120178"] = "Знайдіть НІП «{npc:Ogtinc}» у локації «{zone:Azshara}».",
  ["1e32ea25"] = "Візьміть предмет «{item:Torch of Retribution}».",
  ["1e35ffc3"] = "Павучі яйця лежать у павучих тунелях.",
  ["1e41a639"] = "Вирушайте до майстерні НІП «{npc:Marvon Rivetseeker}» у місцевості «{zone:Ratchet}».",
  ["1e691724"] = "Принесіть предмет «{item:Fel-Tainted Flesh}».",
  ["1ee768e4"] = "Поговоріть з НІП «{npc:Dorn Plainstalker}» у локації «{zone:Thousand Needles}».",
  ["1eedd435"] = "Класове завдання мага.",
  ["1f11c3db"] = "Вирушайте до локації «{zone:Burning Steppes}» і здобудьте «{item:Fractured Elemental Shard}»: 10 шт. для НІП «{npc:Hierophant Theodora Mulvadania}». Ви пам’ятаєте, що, за словами Теодори, ці уламки можна добути з големів і елементалів того краю.",
  ["1f29fa1f"] = "Зберіть «{item:Partially Digested Journal Page}»: 15 шт. у підземеллі «{zone:Shaper's Terrace}».",
  ["20b66310"] = "Поговоріть з НІП «{npc:Brother Anton}» у локації «{zone:Desolace}».",
  ["20fb36d4"] = "Отримайте отруту від боса «{npc:Mother Smolderweb}» і дійдіть до НІП «{npc:Ragged John}», поки вона діє. Не дозволяйте нікому її зняти.",
  ["214ef432"] = "Віднесіть талон на нагороду до НІП «{npc:Dinita Stonemantle}» у місцевості «{zone:Vault of Ironforge}».",
  ["215eedfb"] = "Предмет «{item:Atal'ai Haze}» випадає з храмових черв’яків, причаєнців і слизнів.",
  ["2193b95c"] = "Це завдання можна взяти разом із завданням «{quest:Prison Break In}».",
  ["21a8fa7d"] = "Поточні дані завдань також подають «Таємний інтелект» як нагороду, яку ви вивчаєте.",
  ["21b9ead8"] = "Потрібні попередні кроки ланцюжка «{quest:Hidden Enemies}» у місті «{zone:Orgrimmar}». Наступний крок «{quest:Hidden Enemies}» згодом пропонує:",
  ["21c8c2d6"] = "Принесіть предмет «{item:Libram of Rapidity}», 1 предмет «{item:Pristine Black Diamond}», «{item:Large Brilliant Shard}»: 2 шт. і «{item:Blood of Heroes}»: 2 шт. НІП «{npc:Lorekeeper Lydros}» у підземеллі «{zone:Dire Maul}», щоб отримати предмет «{item:Arcanum of Rapidity}».",
  ["21cc271f"] = "Поверніться до НІП «{npc:Gatekeeper Rageroar}» у місцевості «{zone:Ursolan}».",
  ["2223cf7a"] = "Спершу здайте завдання «{quest:The Archivist}», інакше голова боса «{npc:Balnazzar}» не почне це завдання.",
  ["224ef41c"] = "Поговоріть з НІП «{npc:Tabetha}».",
  ["22569790"] = "Здолайте 2 диверсантів і 4 вартових із клану Драконячої Пащі, заберіть предмет «{item:Dragonmaw Dispatch}» і поверніться з доповіддю до НІП «{npc:Deathstalker Agent}» поза підземеллям.",
  ["227c6187"] = "Віднесіть предмет «{item:Dried Seeds}» до місцевості «{zone:The Stagnant Oasis}» і випробуйте його біля розколини, а потім поверніться до НІП «Тонга».",
  ["22e7e9a0"] = "Знищте вартових біля 5 пілонів, які живлять місцевість «{zone:Prison}» демона «{npc:Immol'thar}». Коли пілони вимкнуться, силове поле навколо демона «{npc:Immol'thar}» зникне. Увійдіть до місцевості «{zone:Prison}» демона «{npc:Immol'thar}» і знищте мерзенного демона в її серці. Нарешті, зійдіться в бою з босом «{npc:Prince Tortheldrin}» у залі «{zone:Athenaeum}». Виконавши завдання, поверніться до НІП «{npc:Shen'dralar Ancient}» у дворі.",
  ["230844b2"] = "Убийте боса «{npc:Bazil Thredd}» у підземеллі «{zone:The Stockade}» і принесіть його голову назад до НІП «{npc:Warden Thelwater}».",
  ["23131580"] = "Убийте «{npc:Ravasaur Matriarch}»: 6, залізношкурих равазаврів: 8 і ще одного НІП у підземеллі «{zone:Shaper's Terrace}».",
  ["23635e58"] = "Веде одразу до завдання «{quest:Underground Assault}».",
  ["23663398"] = "Елітне завдання.",
  ["23c11815"] = "Убийте «{npc:Kobold Digger}»: 4 у місцевості «{zone:Jangolode Mine}» і «{npc:Riverpaw Miner}»: 6 у місцевості «{zone:Gold Coast Quarry}».",
  ["241ce32d"] = "НІП «{npc:Rhapsody Shindigger}» у локації «{zone:The Hinterlands}» просить принести йому «{item:Roc Gizzard}»: 3 шт., «{item:Groddoc Liver}»: 3 шт. і «{item:Ironfur Liver}»: 3 шт.",
  ["24686738"] = "Убийте боса «{npc:Witch Doctor Zum'rah}» і принесіть предмет «{item:Zum'rah's Head}» до НІП «{npc:Archmage Lan'dalock}» у місті «{zone:Dalaran}».",
  ["249dbb36"] = "Шукайте в підземеллі «{zone:Uldaman}» підказки про те, де тепер намисто НІП «Талваш». Убитий паладин, про якого він згадував, мав його останнім.",
  ["24fb9e5d"] = "Знайдіть предмет «{item:Beginnings of the Undead Threat}» і віднесіть його до НІП «{npc:Parqual Fintallas}» у місті «{zone:Undercity}».",
  ["250b235f"] = "Урни — у зовнішній печері підземелля «{zone:Uldaman}», перед його порталом.\n\nНеобов’язкове вступне завдання:",
  ["25262bca"] = "Елітне, рівень 40: зберіть групу. Біля парових озер у локації «{zone:Thousand Needles}» станьте в коло рун і використайте предмет «{item:Corrupted Totems}». Наступають хвилі елементалів, потім елітний шипогрив і «{npc:Ravaging Tempest}», з якого випадає предмет «{item:Eye of the Tempest}» для кожного шамана із цим завданням.",
  ["2547afd3"] = "Мета в західному крилі: предмет «{item:Gauntlet of Gordok Might}» лежить у скрині біля боса «{npc:Prince Tortheldrin}». Саме завдання видає дружній НІП «{npc:Captain Kromcrush}» у північному крилі підземелля «{zone:Dire Maul}», коли ви станете королем Ґордоків.",
  ["254e1701"] = "Здобудьте галети «{item:Enriched Manna Biscuit}»: 20 шт. — головний складник предмета «{item:Manna-Enriched Horse Feed}» — для НІП «{npc:Merideth Carlson}» у місцевості «{zone:Southshore}» у локації «{zone:Hillsbrad Foothills}». Відомо, що єдиний постачальник цих галет — «{npc:The Argent Dawn}». Також треба дати їй 50 золотих, щоб заспокоїти її вражені почуття.",
  ["25566d61"] = "Принесіть предмет «{item:Sharpbeak's Feather}» до НІП «{npc:Thadius Grimshade}» у локації «{zone:Blasted Lands}».",
  ["25704102"] = "Поговоріть із НІП «{npc:Latronicus Moonspear}» у місцевості «{zone:Feathermoon Stronghold}» у локації «{zone:Feralas}».",
  ["25997477"] = "Використайте викривлені тотеми, щоб зірвати ритуал шипогривів.",
  ["25f3773a"] = "Вирушайте до локації «{zone:Burning Steppes}» і передайте предмет «{item:Bijou's Information}» НІП «{npc:Marshal Maxwell}».",
  ["264ba073"] = "Принесіть «{item:Wailing Essence}»: 6 шт. НІП «{npc:Mebok Mizzyrix}».",
  ["26658e14"] = "Зберіть «{item:Fetish of Hakkar}»: 20 шт. з атал’айських тролів; вони випадають і з тролів у зовнішній частині храму.",
  ["26b727de"] = "Книга класу «Воїн». Клацніть на книгу, щоб почати завдання.",
  ["26ce1cf3"] = "Поговоріть із воєначальником Ґортутом, щоб отримати від нього предмет-наказ, і клацніть по ньому, щоб почати завдання. Предмет «{item:Important Blackrock Documents}» з’являється біля трьох генералів.",
  ["26f2ab7d"] = "Увага: якщо не виконати це завдання до прийняття завдання «{quest:Blackfathom Villainy}», воно стане недоступним.",
  ["2745b5b8"] = "Поговоріть із привидом Франклорна у вигляді духа. Убийте боса «{npc:Fineous Darkvire}» заради предмета «{item:Ironfel}» і покладіть молот на пам’ятник Франклорну біля арени. Предмет «{item:Shadowforge Key}» відкриває скорочені шляхи в Глибинах Блекрок.",
  ["278b9ec1"] = "Убивайте ворогів у зовнішній частині підземелля «{zone:Gnomeregan}», доки не випаде предмет «{item:White Punch Card}».",
  ["27c61a0f"] = "Доступне після завдання «{quest:Prison Break In}».",
  ["27cab65b"] = "Останній крок. Нагорода — предмет «{item:Verigan's Fist}».",
  ["2818f7d7"] = "Увійдіть до підземелля «{zone:Alcaz Prison}» і зберіть «{item:Blood Red Bandana}»: 8 шт. з тамтешніх вартових-людей.",
  ["2864bb7d"] = "Поговоріть із НІП «{npc:Jaron Stoneshaper}» у місцевості «{zone:Starfall Village}».",
  ["28691bad"] = "Відрахуйте сто кроків точно на північ від табору і знайдіть «{zone:Mound of Dirt}» під скелею.",
  ["2895ec1a"] = "Здобудьте «{item:Young Crocolisk Skin}»: 4 шт. для НІП «{npc:James Halloran}» у місцевості «{zone:Menethil Harbor}».",
  ["2908ffe6"] = "Позичте намисто НІП «Джаркал». Натомість він перекладе для вас журнал.",
  ["294abaf6"] = "Потрібне перед завданням «{quest:Highland Hides}». Завдання «{quest:Daily Delivery}» тут не потрібне.",
  ["2958b5be"] = "Вирушайте до підземелля «{zone:Scholomance}» і поверніть статок родини Баров. Цей статок складають чотири купчі: купча на «{zone:Caer Darrow}»; купча на «{zone:Brill}»; купча на «{zone:Tarren Mill}»; і купча на «{zone:Southshore}». Виконавши це, поверніться до НІП «{npc:Alexi Barov}».",
  ["2968e9ba"] = "Зробіть відбитки чотирьох табличок у підземеллі «{zone:The Drowned City}».",
  ["29c2fdff"] = "Якщо хочете допомогти місцевому НІП у місцевості «{zone:Valley of Wisdom}» міста «{zone:Orgrimmar}», принесіть йому предмети «{item:Azerothian Diamond}» і «{item:Pristine Black Diamond}».",
  ["29c318c2"] = "Після попереднього завдання. Ланцюжок триває в місті «{zone:Stormwind}» і веде аж до завдання в підземеллях «{zone:Maraudon}» і «{zone:Blackrock Depths}».",
  ["29e98766"] = "Доставте предмет «{item:Dark Iron Map}» до НІП «{npc:Earthseer Farsen}» у локації «{zone:Dun Morogh}».",
  ["2a190ff1"] = "Здобудьте предмет «{item:The Lost Magic of the Runemasters}» у підземеллі «{zone:Scarlet Monastery}».",
  ["2a703f81"] = "Зберіть «{item:Bloodied Insignia}»: 10 шт.",
  ["2ac884a4"] = "Знищте «{npc:Twilight Ritual Circle}»: 5 у печерах під місцевістю «{zone:Sunnyglade}».",
  ["2b78ba16"] = "Схоже, виставу закінчено. Ви знаєте, що предмет «{item:Amulet of Draconic Subversion}», який зробила для вас НІП «{npc:Myranda the Hag}», не діятиме в підземеллі «{zone:Blackrock Spire}». Можливо, варто знайти НІП «{npc:Rexxar}» і пояснити, у якій ви скруті. Покажіть йому предмет «{item:Dull Drakefire Amulet}». Сподіваймося, він знатиме, що робити далі.",
  ["2b7d8249"] = "Ви наносите їх на карту за допомогою предмета «{item:Explorers' League Cartographer's Kit}».",
  ["2c03a0b9"] = "Печера — у місцевості «{zone:Sunken Hollow}», під водою близько 21, 28: це вхід до підземелля «{zone:The Drowned City}».",
  ["2c07904d"] = "Поговоріть з НІП «{npc:Tran'rek}» у місті «{zone:Gadgetzan}».",
  ["2c3e7ae6"] = "Зберіть «{item:Nordrassil Root Cap}»: 10 шт. у підземеллі «{zone:Blackmaw Hold}».",
  ["2ce1d079"] = "Поговоріть з НІП «{npc:Wiley the Black}» у місцевості «{zone:Lakeshire}».",
  ["2d0d7f34"] = "Для запланованого вибуху вам потрібен віддалений детонатор.",
  ["2d5485a6"] = "Скористайтеся предметом «{item:Jaron's Pick}», щоб знайти чотири уламки реліквій. Принесіть їх до НІП «{npc:Aurora Skycaller}» у локації «{zone:Eastern Plaguelands}».",
  ["2d85452d"] = "Поговоріть з НІП «{npc:Lord Jorach Ravenholdt}» у місцевості «{zone:Ravenholdt Manor}».",
  ["2d97ec52"] = "Випадкова здобич; зазвичай вона випадає під час першої зачистки зовнішньої частини.",
  ["2db2cb9a"] = "Передайте предмет «{item:Tinkee's Letter}» НІП «{npc:Felnok Steelspring}».",
  ["2e05cfac"] = "Принесіть «{item:Carved Stone Urn}»: 4 шт. НІП «{npc:Prospector Ironband}» у локації «{zone:Loch Modan}».",
  ["2e60650b"] = "Поговоріть з НІП «{npc:Shadowmage Vivian Lagrave}» у місцевості «{zone:Kargath}».",
  ["2e7a7cd4"] = "Убийте боса «{npc:Princess Theradras}» і поверніться до НІП «{npc:Keeper Marandis}» на заставі «{zone:Nijel's Point}» у локації «{zone:Desolace}».",
  ["2eac173f"] = "Повторюване. Спершу треба здати завдання «{quest:Elven Legends}» вашої фракції.",
  ["2ec1cbd7"] = "Вилікуйте НІП (за повідомленнями гравців — до повного здоров’я).",
  ["2ec3d179"] = "Принесіть «{item:Magenta Fungus Cap}»: 12 шт. НІП «{npc:Jarkal Mossmeld}» у місцевості «{zone:Kargath}».",
  ["2f5849b0"] = "Принесіть предмети «{item:High Potency Radioactive Fallout}» і «{item:Heavy Leaden Collection Phial}» назад до цього НІП. Опади швидко розпадаються.",
  ["2f6639d8"] = "Принесіть предмет «{item:Darkstone Tablet}» замовникові у місцевості «{zone:Kargath}».",
  ["304e6214"] = "Якщо застосувати модуль до яєць у місцевості «{zone:The Rookery}», з них можуть вилупитися дракончики.",
  ["3092b561"] = "Групове завдання: місцеві мурлоки у місцевості «{zone:The Vile Reef}» елітні.",
  ["30ac6e8a"] = "Знайдіть орлине гніздо на стіні греблі «{zone:Stonewrought Dam}» у локації «{zone:Loch Modan}»: там лежить фігурка.",
  ["30eec9b4"] = "Убийте боса в підземеллі «{zone:The Drowned City}».",
  ["312c74c0"] = "Поговоріть з НІП «{npc:Warden Thelwater}» біля входу в підземелля «{zone:The Stockade}».",
  ["313845c1"] = "НІП «{npc:Mithera}» пропонує його, щойно ви здасте завдання «{quest:Forlorn Gardens}».",
  ["3193ec21"] = "Вистежте НІП «{npc:Defias Messenger}» у локації «{zone:Westfall}» і принесіть його повідомлення до НІП «{npc:Gryan Stoutmantle}».",
  ["31adc48a"] = "Принесіть предмет «{item:Orb Fragments}» до НІП «{npc:Delgren the Purifier}» у локації «{zone:Ashenvale}». Нагорода: предмет «{item:Cloak of the Divine Storm}».",
  ["31db1c01"] = "Убийте боса «{npc:General Drakkisath}» наприкінці Верхнього Шпиля Блекрок.",
  ["31e0b7de"] = "Вирушайте до місцевості «{zone:Ruins of Thaurissan}» («{zone:Burning Steppes}») і зберіть відомості з тамтешніх реліквій. Зібравши їх, поверніться до НІП «{npc:Royal Historian Archesonus}».",
  ["3225dab0"] = "Купіть предмет «{item:Xorothian Stardust}» у НІП «{npc:Ur'dan}». Принесіть його до НІП «{npc:Gorzeeki Wildeyes}» у локації «{zone:Burning Steppes}».",
  ["324351d4"] = "Принесіть предмет «{item:Fragments of Rok'Alim}» до НІП «{npc:Dorn Plainstalker}» у локації «{zone:Thousand Needles}».",
  ["32516866"] = "Взаємодійте зі скелетними рештками поруч із НІП «{npc:Lorekeeper Lydros}» у залі «{zone:Athenaeum}». Відкриває обміни лібрамів у Лідроса.",
  ["3254a73e"] = "Класове завдання паладина для людей і дворфів. У цьому підземеллі предмет «{item:Whitestone Oak Lumber}» випадає з гоблінів-різьбярів. Інші частини: «{item:Jordan's Smithing Hammer}» («{zone:Shadowfang Keep}»), «Самоцвіт Кор» («{zone:Blackfathom Deeps}») і партія руди НІП «Джордан» («{zone:Loch Modan}»).",
  ["3275e953"] = "Ці двоє ворогів ходять різними шляхами: пройдіть обидва.",
  ["3294b886"] = "Веде до завдання «{quest:General Drakkisath's Demise}» у Верхньому Шпилі Блекрок.",
  ["32bcb16a"] = "Поверніться до міста «{zone:Ironforge}» і повідомте погану новину НІП «{npc:King Magni Bronzebeard}».",
  ["32c1a573"] = "«{npc:Nara Wildmane}» — остання умова, перш ніж стане доступним завдання «{quest:Leaders of the Fang}».",
  ["334f7817"] = "Принесіть «{item:Magenta Fungus Cap}»: 12 шт. НІП «{npc:Ghak Healtouch}» у місцевості «{zone:Thelsamar}».",
  ["339931e3"] = "Поверніться до НІП «{npc:Magistrate Marduke}» у місцевості «{zone:Caer Darrow}». Покажіть йому предмет «{item:Soulbound Keepsake}».",
  ["33a8239b"] = "Навідайтеся до НІП «{npc:Jarkal Mossmeld}» у місцевості «{zone:Kargath}» і дізнайтеся, чи йому вдалося.",
  ["34030fef"] = "Групове завдання: НІП «{npc:Riptear}» — елітний ворог 13-го рівня.",
  ["341016f0"] = "Другий крок ланцюжка «{quest:The Defias Brotherhood}».",
  ["3479a707"] = "Поговоріть з НІП «{npc:Ott}» і попросіть його викувати ваш клинок.",
  ["349c0ce4"] = "Вступний крок до завдання «{quest:Voodoo Feathers}».",
  ["349ccba3"] = "Сапфір випадає з боса «{npc:Grimlok}», а джерело енергії — з боса «{npc:Archaedas}».",
  ["34c98da2"] = "Убийте боса «{npc:Mekgineer Thermaplugg}» і поверніться до НІП «{npc:High Tinker Mekkatorque}».",
  ["34f52252"] = "Книга класу «Маг». Клацніть на книгу, щоб почати завдання.",
  ["3504ba35"] = "Захопіть духів 3 верескунів у локації «{zone:Feralas}», потім поверніться до НІП «{npc:Yeh'kinya}» у місцевості «{zone:Steamwheedle Port}».",
  ["3540a053"] = "Зустріньтеся із замовником у локації «{zone:Dustwallow Marsh}» і дізнайтеся більше про своє завдання.",
  ["3552b40c"] = "Вступний крок до завдання «{quest:A Better Ingredient}».",
  ["355717d9"] = "Зберіть «{item:Intact Limbs}»: 25 шт. у підземеллі «{zone:Ruins of Lordaeron}».",
  ["35991dd8"] = "Принесіть п’яту й шосту таблички Мош’ару до НІП «{npc:Prospector Ironboot}» у локації «{zone:Tanaris}».",
  ["35e85f85"] = "Вирушайте до порталу в рейд «{zone:Molten Core}» у підземеллі «{zone:Blackrock Depths}» і здобудьте предмет «{item:Core Fragment}». Здобувши предмет «{item:Core Fragment}», поверніться до НІП «{npc:Lothos Riftwaker}» у місцевості «{zone:Blackrock Mountain}».",
  ["36792697"] = "Поговоріть з НІП «{npc:Highlord Bolvar Fordragon}» після розмови з НІП «{npc:Lady Katrana Prestor}».",
  ["36d3adf7"] = "Зберіть «{item:Bloodpetal}»: 15 шт. і поверніться до НІП «{npc:Muigin}».",
  ["3723f055"] = "Спершу поговоріть із Кам’яним вартовим і активуйте диски. Потім віддайте талон на нагороду НІП «{npc:Dinita Stonemantle}» у сховищі міста «{zone:Ironforge}» і виберіть нагороду.",
  ["37266793"] = "Здолайте боса «{npc:Lorgus Jett}» у підземеллі «{zone:Blackfathom Deeps}».",
  ["374d01ec"] = "Потрібне перед завданнями культу «{npc:Twilight's Hammer}» (за повідомленням гравця спільноти).",
  ["375ca6f4"] = "Вирушайте до підземелля «{zone:Scholomance}» і поверніть статок родини Баров. Цей статок складають чотири купчі: купча на «{zone:Caer Darrow}»; купча на «{zone:Brill}»; купча на «{zone:Tarren Mill}»; і купча на «{zone:Southshore}». Виконавши це, поверніться до НІП «{npc:Weldon Barov}».",
  ["377d810f"] = "Заберіть плату від замовника в схованці біля місцевості «{zone:Pyrewood Village}».",
  ["37d038f7"] = "Посланець ходить дорогами між місцевостями «{zone:Moonbrook}», «{zone:Gold Coast Quarry}» і «{zone:Jangolode Mine}».",
  ["3824bc40"] = "Вступний крок до завдання «{quest:Lost Thunderbrew Recipe}».",
  ["3839de23"] = "Поговоріть із НІП «{npc:Tinkee Steamboil}».",
  ["383a526f"] = "Поверніться до підземелля «{zone:Scholomance}» з предметом «{item:Blood of Innocents}». Знайдіть ґанок і покладіть предмет «{item:Blood of Innocents}» у жаровню. Кіртонос прийде поласувати вашою душею. Бийтеся відважно, не відступайте ні на крок! Знищте Кіртоноса й поверніться до НІП «{npc:Eva Sarkhoff}».",
  ["3865ced2"] = "Знайдіть НІП «{npc:Woodwyrd}» у місцевості «{zone:Forlorn Gardens}» у локації «{zone:Shen'dralas}».",
  ["388891a6"] = "Здолайте боса «{npc:Edwin VanCleef}» і заберіть його голову.",
  ["38c4dd06"] = "Зберіть «{item:Twilight Bangle}»: 8 шт. з членів культу «{npc:Twilight's Hammer}» у підземеллі «{zone:Krol'dok Stronghold}».",
  ["390c953a"] = "Знайдіть НІП «{npc:Sergeant Riftan}» поблизу місцевості «{zone:Twilight's Shroud}» на заході.",
  ["3981d599"] = "Зберіть «{item:Red Wool Bandana}»: 10 шт. з в’язнів Дефіасу в підземеллі «{zone:The Stockade}».",
  ["39ec3bf0"] = "Павутина випадає з боса «{npc:Lethtendris}».\n\nНеобов’язкове вступне завдання:",
  ["3a075135"] = "Предмет «{item:Fragment of the Firelands}» випадає з НІП «{npc:Magmus}», вартового біля дверей до місцевості «{zone:The Imperial Seat}» у підземеллі «{zone:Blackrock Depths}». Його бачили підібраним на 49 рівні.",
  ["3a08ada7"] = "Попередження: приймайте це завдання лише після виконання завдання «%s», інакше те завдання буде втрачено.",
  ["3a29632b"] = "Знайдіть тютюнову крамницю НІП «{npc:Fras Siabi}» у підземеллі «{zone:Stratholme}» і здобудьте коробку тютюну. Коли впораєтеся, поверніться до НІП «{npc:Smokey LaRue}».",
  ["3a42abfa"] = "Доставте предмет «{item:Titan Relic}» до НІП «{npc:High Explorer Magellas}» у місцевості «{zone:Hall of Explorers}».",
  ["3a5728ae"] = "Поговоріть з НІП «{npc:Mathrengyl Bearwalker}» у місцевості «{zone:Cenarion Enclave}» у місті «{zone:Darnassus}».",
  ["3a825549"] = "НЕОБОВ’ЯЗКОВЕ, можна пропустити",
  ["3a9d6d87"] = "Принесіть роги «{item:Uncracked Chillwind Horn}»: 8 шт. до НІП «{npc:Felnok Steelspring}».",
  ["3ab99969"] = "Кров Ґрома, велетенські срібні жили (скельні велетні в локації «{zone:Azshara}») і фіал, наповнений у місцевості «{zone:Golakka Hot Springs}» у Кратері Ун'Ґоро. Відкриває мирний прохід через бар під час наступних відвідин.",
  ["3acb4315"] = "Зберіть «{item:Heart of Flame}»: 4 і «{item:Golem Oil}»: 4 та віднесіть їх НІП «{npc:Velarok Windblade}».",
  ["3ad1391f"] = "Вам треба знайти у світі істоту, здатну відновити силу предмета «{item:Fragment of the Dragon's Eye}». Усе, що ви знаєте про таку істоту, — що вона існує.",
  ["3b1ef548"] = "Вступний крок до завдання «{quest:Hurley Blackbreath}».",
  ["3bb83a76"] = "Гравець Орди не може почати завдання з намиста: спершу потрібно вже мати це завдання.",
  ["3bcb18bf"] = "Таблички випадають із босів «{npc:Theka the Martyr}» і «{npc:Hydromancer Velratha}».",
  ["3bea384c"] = "Принесіть предмет «{item:Prismatic Punch Card}» до НІП «{npc:Master Mechanic Castpipe}» у місті «{zone:Ironforge}».",
  ["3c6974bf"] = "Принесіть «{item:Essential Artificial}»: 12 шт. до НІП «{npc:Klockmort Spannerspan}» у місті «{zone:Ironforge}».",
  ["3c7d88da"] = "Предмет «{item:Garrett Family Treasure}» лежить у родинній скрині поза підземеллям.",
  ["3c948345"] = "Повідомте НІП «{npc:Marshal Maxwell}» погану новину.",
  ["3ca5cee8"] = "НІП «{npc:Scarshield Quartermaster}» стоїть у коридорі біля порталу до місцевості «{zone:The Spire}». Торкніться «{zone:Drakkisath's Brand}» за босом «{npc:General Drakkisath}»: це відкриває швидкий шлях через ланцюжок завдань до рейду «{zone:Blackwing Lair}».",
  ["3cc63c16"] = "Поговоріть з НІП «{npc:Marshal Maxwell}» у локації «{zone:Burning Steppes}».",
  ["3dbc2fb4"] = "Пошукайте в підземеллі «{zone:Dire Maul}» зниклого НІП. Повідомте все, що дізнаєтеся, НІП «{npc:Scholar Runethorn}» у фортеці Фезермун.",
  ["3e23bb96"] = "Здобудьте предмет «{item:Blackmaw Ritual Totem}» з одного з ворогів у підземеллі «{zone:Blackmaw Hold}».",
  ["3e3a0955"] = "Якщо ви в групі з іншими паладинами, лише один із вас зможе підібрати записку, яку впускає цей НІП («{item:Bloody Missive}»). Якщо ви її не отримали, не здавайте це завдання трактирнику: скасуйте його й почніть знову.",
  ["3e40eef5"] = "Принесіть предмет «{item:Lost Thunderbrew Recipe}» до НІП «Вівіан Лаґрейв» у місцевості «{zone:Kargath}».",
  ["3e5122bd"] = "Вирушайте до північних кордонів локації «{zone:Eastern Plaguelands}» і здобудьте предмет «{item:Quel'Thalas Registry}». Він десь у мисливському будинку. Також убийте «{npc:Ranger}»: 8, «{npc:Pathstrider}»: 8 і «{npc:Woodsman}»: 8.",
  ["3ea9ba68"] = "Зберіть «{item:Dwarven Heirloom}»: 8 шт. у підземеллі «{zone:The Hall of Thanes}».",
  ["3f1d087a"] = "Знайдіть предмет «{item:Talisman of Kazdor}» у підземеллі «{zone:Zul'Farrak}». Потім віднесіть його до НІП «{npc:Fahrad}» у місцевості «{zone:Ravenholdt Manor}». Виконати завдання потрібно самостійно.",
  ["3fb6a161"] = "Джерело енергії випадає з боса «{npc:Archaedas}». Виконання відкриває предмет «{item:Talvash's Enhancing Necklace}».",
  ["3fc0f20d"] = "Предмет «{item:Core Fragment}» лежить на камені біля порталу в рейд «{zone:Molten Core}» далеко в Глибинах Блекрок. Відкриває телепорт від Лотоса в рейд «{zone:Molten Core}».",
  ["3ff535e6"] = "Поговоріть з НІП «{npc:Lumina Windsinger}» у місцевості «{zone:The Sepulcher}».",
  ["4055c389"] = "У новіших записах гри його звуть інакше. Зачистьте тютюнову крамницю, торкніться коробки з тютюном і вбийте крамаря.",
  ["40927876"] = "Використайте предмет «{item:Well Water Sample Kit}» біля колодязів у місцевостях «{zone:The Jansen Stead}» і на сусідній фермі.",
  ["413a4e4e"] = "Поговоріть з НІП «Гамуул Рунотем» у місцевості «{zone:Elder Rise}» міста «{zone:Thunder Bluff}».",
  ["413b1614"] = "Вирушайте до підземелля «{zone:Blackrock Spire}» і з’ясуйте, що сталося з НІП «{npc:Bijou}».",
  ["4176b74e"] = "Заберіть предмет «{item:Gnoam Sprecklesprocket}» у боса «{npc:Sneed's Shredder}».",
  ["41c8734c"] = "Принесіть «{item:Bolt of Runecloth}»: 4 шт., «{item:Rugged Leather}»: 8 шт., «{item:Rune Thread}»: 2 шт. і предмет «{item:Ogre Tannin}» НІП «{npc:Knot Thimblejack}». Зараз він закутий у кайдани в крилі Ґордоків підземелля «{zone:Dire Maul}».",
  ["41cc00c3"] = "Останній крок. НІП «{npc:Ambassador Malcin}» стоїть перед входом до підземелля «{zone:Razorfen Downs}».",
  ["420c41c1"] = "Вступний крок до завдання «{quest:Gahz'rilla}».",
  ["423e6d10"] = "НІП «{npc:Commander Aggro'gosh}» видає його, щойно здано завдання «{quest:The Gurubashi Legends of Old}».",
  ["427a1a25"] = "Застосуйте предмет «{item:Exorcism Censer}», щоб вигнати духів, які мучать місцевість «{zone:Terrordale}». Коли вб’єте духів «{npc:Terrordale Spirit}»: 25, поверніться до НІП «{npc:Lord Grayson Shadowbreaker}» у місті «{zone:Stormwind}».",
  ["427c70f3"] = "Убийте ворга «{npc:Halycon}», матір воргового лігва. Будьте готові до появи боса «{npc:Gizrul the Slavener}», який прийде по вас одразу після неї.",
  ["42aab8bd"] = "Убийте НІП «{npc:Riptear}» на північному сході локації «{zone:Tirisfal Glades}» і принесіть предмет «{item:Riptear's Heart}» до НІП «{npc:Deathguard Linnea}».",
  ["431c892c"] = "Зберіть «{item:Seeping Slime Essence}»: 8 шт. у підземеллі «{zone:Shaper's Terrace}».",
  ["43d211ab"] = "Знайдіть боса «{npc:Jandice Barov}» у підземеллі «{zone:Scholomance}» і знищте її. Заберіть із її тіла предмет «{item:Krastinov's Bag of Horrors}». Поверніть торбу до НІП «{npc:Eva Sarkhoff}».",
  ["44024f47"] = "Предмет «{item:Tablet of Ryun'eh}» лежить у скрині поза підземеллям.",
  ["4414e2c0"] = "Віднесіть предмет «{item:Wiley's Note}» назад до НІП «{npc:Gryan Stoutmantle}» у локації «{zone:Westfall}».",
  ["4452a134"] = "Принесіть вусики силітидів: 5 шт. до НІП «{npc:Ruga Ragetotem}» у таборі «{zone:Camp Taurajo}».",
  ["4452c915"] = "Зберіть «{item:Fetish of Hakkar}»: 20 шт. і принесіть їх до НІП «Фел’зерул» у місцевості «{zone:Stonard}».",
  ["4469b055"] = "Віднесіть предмет «{item:Small Scroll}» до НІП «{npc:Varimathras}» у місті «{zone:Undercity}».",
  ["451f5892"] = "Коли бос «{npc:Baron Rivendare}» загине, застосуйте сяйну руну на підлозі його кімнати, а потім поверніться з наступним завданням до Леоніда.",
  ["45260ce3"] = "Принесіть предмет «{item:Tooth of Morphaz}» до НІП «{npc:Ogtinc}» у локації «{zone:Azshara}». НІП «{npc:Ogtinc}» живе на вершині скель на північний схід від місцевості «{zone:Ruins of Eldarath}».",
  ["45941379"] = "Класове завдання мага. Предмет «{item:Arcane Shard}» випадає з боса «{npc:Morphaz}».\n\nНеобов’язкове вступне завдання:",
  ["45a75f9f"] = "Потрібне перед завданням «{quest:Open the Maw}».",
  ["45fd54ab"] = "Зберіть «{item:Longshore Murloc Gill}»: 7 шт. на узбережжі локації «{zone:Westfall}».",
  ["4603789e"] = "Здолайте боса «{npc:Twilight Lord Kelris}» і заберіть предмет «{item:Head of Kelris}».",
  ["462b0c6a"] = "Це завдання виконується ПОЗА цим підземеллям: зробіть його до входу в підземелля.",
  ["46445721"] = "Принесіть пера вуду до НІП «Ашлам Валорфіст».",
  ["468d89af"] = "Перший обов’язковий крок до завдання «{quest:The Stockade Riots}».",
  ["46cd35fa"] = "Знайдіть НІП «Ремулос» у локації «{zone:Moonglade}» і віддайте йому предмет «{item:Seed of Life}».",
  ["46f252d1"] = "Вступний крок до завдання «{quest:Fragments of the Past}».",
  ["47009dc4"] = "Поговоріть з НІП «{npc:Deathguard Baldren}» про загадкових мандрівників Земляного Кільця, які нещодавно проходили через місцевість «{zone:The Sepulcher}».",
  ["4818689a"] = "Це відкриває завдання в місцевості «{zone:Shen'dralas}», зокрема завдання НІП «{npc:Mithera}».",
  ["48327f09"] = "Віднесіть невикувану печатку й предмет «{item:Orb of Draconic Energy}» до дрейка «{npc:Emberstrife}» у місцевості «{zone:Wyrmbog}» у локації «{zone:Dustwallow Marsh}». Викувана печатка відчиняє двері Верхнього Шпиля Блекрок.",
  ["4863bc64"] = "Поговоріть із НІП «{npc:Mayara Brightwing}» у локації «{zone:Burning Steppes}».",
  ["490e7b2a"] = "Убийте боса «{npc:Overmaster Pyron}» і поверніться до НІП «{npc:Jalinda Sprig}». Ви пам’ятаєте, як Джалінда казала, що Пайрон охороняє каменоломню. Може, варто пошукати там?",
  ["4946cde2"] = "Прочитайте цю табличку, щоб дізнатися ім’я бога-павука цього племені, потім поверніться до НІП «{npc:Master Gadrin}».",
  ["497f9297"] = "Повернувшись у місцевість «{zone:Forlorn Gardens}», використайте флакон на палаючому дереві поруч із НІП «{npc:Woodwyrd}», а не на НІП «{npc:Woodwyrd}». Потім НІП «{npc:Woodwyrd}» відправляє вас до місцевості «{zone:Bristleback Retreat}» (наступне завдання), а звідти ланцюжок веде далі.",
  ["49f71b16"] = "Знайдіть предмет «{item:Bijou's Belongings}» і поверніть його власниці. Ви пригадуєте, як вона казала, що сховала речі на нижньому поверсі міста.",
  ["4a07884f"] = "Ваш наставник воїнів (у місті «{zone:Orgrimmar}») спершу відправляє вас до НІП, що видає це завдання. Ліміт часу: 30 хвилин. Вусики випадають із силітидів на полі «{zone:Field of Giants}», на південь від табору «{zone:Camp Taurajo}».",
  ["4a6b64a2"] = "Принесіть предмет «{item:Voodoo Feathers}» від тролів із підземелля «{zone:Sunken Temple}» до НІП «{npc:Fallen Hero of the Horde}».",
  ["4b03ee0c"] = "Це ланцюжок завдань із кроком у підземеллі «{zone:Blackfathom Deeps}»",
  ["4b38636e"] = "Принесіть «{item:Uncracked Scarab Shell}»: 5 шт. НІП «{npc:Tran'rek}» у місті «{zone:Gadgetzan}».",
  ["4b5d1650"] = "Книга класу «Шаман». Клацніть на книгу, щоб почати завдання.",
  ["4c13d08d"] = "Вступний крок до завдання «{quest:The Azure Key}».",
  ["4c7c7f3e"] = "Знайдіть впливового свинобраза в місцевості «{zone:Bristleback Retreat}».",
  ["4cb3f3bd"] = "Частина допуску до боса «{npc:Onyxia}».",
  ["4cc054f0"] = "Використайте предмет «{item:Empty Leaden Collection Phial}» на опромінених загарбниках або опромінених грабіжниках, потім віднесіть повну колбу до НІП «{npc:Ozzie Togglevolt}».",
  ["4d22b897"] = "НІП «{npc:Zaetar's Spirit}» з’являється після смерті боса «{npc:Princess Theradras}».",
  ["4d242629"] = "Віднесіть предмет «{item:An Unsent Letter}» від НІП «{npc:Edwin VanCleef}» до НІП «{npc:Baros Alexston}» у місті «{zone:Stormwind}».",
  ["4d678e4a"] = "Убийте «{npc:Defias Prisoner}»: 10, «{npc:Defias Convict}»: 8 і «{npc:Defias Insurgent}»: 8 у підземеллі «{zone:The Stockade}».",
  ["4d7a2218"] = "Віднесіть ваучер нагороди до НІП «{npc:Bena Winterhoof}» у місті «{zone:Thunder Bluff}».",
  ["4dcabca9"] = "НІП «{npc:Bijou}» ховається в ніші за першими мостами. Її речі з’являються в одному з кількох місць біля залів тролів та орків.",
  ["4dd78acb"] = "Доставте голову до міста огрів на півночі.",
  ["4e4487c1"] = "Принесіть предмет «{item:Blood-Stained Letter}» до НІП «{npc:Orphan Matron Nightingale}».",
  ["4e470302"] = "Знайдіть предмет «{item:Hammertoe's Amulet}» і поверніть його власникові в підземеллі «{zone:Uldaman}».",
  ["4e5b7765"] = "Предмет «{item:Document Box}» продається за 25 золотих АБО починає завдання:",
  ["4e7cbe2a"] = "Це ланцюжок завдань із кроком у підземеллі «{zone:The Deadmines}»",
  ["4e87a377"] = "Вирушайте до підземелля «{zone:Blackrock Spire}» і знищте боса «{npc:General Drakkisath}». Коли впораєтеся, поверніться до НІП «{npc:Marshal Maxwell}».",
  ["4e8f86a5"] = "Другий обов’язковий крок перед завданням «{quest:Horrors in the Highland}».",
  ["4e947f9b"] = "Віднесіть лист міському архітекторові в місті «{zone:Stormwind}».",
  ["4ea6d7b9"] = "Увійдіть до цього підземелля і здобудьте предмет «{item:Durgen Dirgehammer's Head}».",
  ["4ec34ffa"] = "Увійдіть до підземелля «{zone:Blackrock Depths}» і вистежте НІП «{npc:Lord Incendius}». Убийте його й принесіть до НІП «{npc:Thunderheart}» усі джерела відомостей, які знайдете.",
  ["4ed68c6c"] = "Щоб поговорити з ним, треба бути мертвим. Він у місцевості «{zone:Blackrock Mountain}», у кімнаті на шляху ланцюгом униз до Глибин Блекрок.",
  ["4f11a4cc"] = "Виконання завдання «{quest:Altered Beings}» відкриває доступ до завдання «{quest:Hamuul Runetotem}».",
  ["4f351bae"] = "Заберіть найцінніший скарб НІП «{npc:Krom Stoutarm}» з його скрині в залі «{zone:North Common Hall}» підземелля «{zone:Uldaman}» і принесіть йому в місто «{zone:Ironforge}».",
  ["4f4a7321"] = "Зберіть «{item:Grizzled Bear Heart}»: 6 шт. і 6 зразків предмета «{item:Skittering Blood}» та доставте їх до НІП «{npc:Master Apothecary Faranell}» у місті «{zone:Undercity}».",
  ["4f7f24d0"] = "Тіара випадає з боса «{npc:Hydromancer Velratha}».\n\nНеобов’язкове вступне завдання:",
  ["4f8a26d3"] = "Убийте боса «{npc:Lord Incendius}» біля ковадла в Глибинах Блекрок.",
  ["500e628f"] = "Убийте «{npc:Bleeding Horror}»: 8 і «{npc:Wandering Spirit}»: 8, а потім поверніться з доповіддю до НІП «Ліннея» в її табір.",
  ["504b452a"] = "Знайдіть НІП «{npc:Borelgore}» у північних пустищах локації «{zone:Eastern Plaguelands}» і знищте його. Виконавши це, поверніться до НІП «{npc:Nathanos Blightcaller}».",
  ["507b0750"] = "Предмет на вибір видають у наступному кроці, «{quest:Unending Torment}», у місті «{zone:Undercity}».",
  ["507dff81"] = "Диски — у залі «{zone:Map Chamber}», за босом «{npc:Ironaya}».",
  ["509194c7"] = "По одному кристалу в кожному таборі кентаврів у локації «{zone:Desolace}».",
  ["5095ea12"] = "Знайдіть тавро, яке охороняє бос «{npc:General Drakkisath}», і отримайте з нього знак, щоб користуватися сферою командування.",
  ["5106be4b"] = "Знайдіть предмет «{item:Sacred Highborne Writings}» у місцевості «{zone:Temple of Zin-Malor}» у локації «{zone:Azshara}» і принесіть його до НІП «{npc:Aurora Skycaller}» біля місцевості «{zone:Northpass Tower}» у локації «{zone:Eastern Plaguelands}».",
  ["5109d569"] = "Наповніть флакон «{item:Coated Cerulean Vial}» у басейні з помаранчевими кристалами в підземеллі «{zone:Maraudon}». Використайте «{item:Filled Cerulean Vial}» на ліанах, щоб змусити зіпсованих паростків «{npc:Noxxious Scion}» вийти. Зцілте 8 рослин, убиваючи паростків «{npc:Noxxious Scion}», потім поверніться до НІП «{npc:Talendria}» на заставі «{zone:Nijel's Point}».",
  ["516a55a1"] = "За допомогою предмета «{item:Jordan's Weapon Notes}» знайдіть «{item:Whitestone Oak Lumber}», партію руди, «{item:Jordan's Smithing Hammer}» і «Самоцвіт Кор» та поверніть їх до НІП «{npc:Jordan Stilwell}» у місті «{zone:Ironforge}».",
  ["51c37d3c"] = "Потрібно виконати крок ланцюжка «{quest:The Defias Brotherhood}» із супроводом.",
  ["51ce180b"] = "Доставте предмет «{item:Titan Relic}» до НІП «{npc:Prospector Whelgar}» на місці розкопок у локації «{zone:Wetlands}».",
  ["51f9254a"] = "Знайдіть цікаві орієнтири в підземеллі «{zone:Shaper's Terrace}» і біля кожного заповніть карту дослідника: «{zone:Pillar of Assimilation}», кристал, західні ворота, «{zone:Regrowth Vestibule}» і відкопаний Кам’яний вартовий.",
  ["520a34dd"] = "Обидва перебувають у місцевості «{zone:Balnir Farmstead}», на схід від табору НІП «Ліннея».",
  ["520d7135"] = "Віднесіть предмет «{item:Savage Coast Report Bundle}» (фетиші, легенди тролів і звіт розвідки) до НІП «{npc:Loremaster Dibbs}» у місцевості «{zone:Southshore}».",
  ["520f4ec6"] = "Знайдіть НІП «{npc:Sanath Lim-yo}» і отримайте дозвіл пройти до НІП «{npc:Archmage Xylem}».",
  ["52648c18"] = "Вступний крок до завдання «{quest:Doomrigger's Clasp}».",
  ["52ca4e1d"] = "Убийте «{npc:Plaguebat}»: 30 і поверніться до НІП «{npc:Tirion Fordring}».",
  ["52db9756"] = "Убийте «{npc:Razorfen Battleguard}»: 8, «{npc:Razorfen Thornweaver}»: 8 і «{npc:Death's Head Cultist}»: 8 та поверніться до НІП «{npc:Myriam Moonsinger}» біля входу в підземелля «{zone:Razorfen Downs}».",
  ["52ed8626"] = "Розкажіть командирові, що ви знайшли.",
  ["52f7f734"] = "Розслідуйте зникнення НІП «Едвард Гартвівер» у підземеллі «{zone:Ruins of Lordaeron}».",
  ["53220682"] = "Вирушайте до підземелля «{zone:Blackrock Spire}» і знайдіть цуценят воргів Кривавої Сокири. Переносьте цих лютих звірят у клітці. Принесіть предмет «{item:Caged Worg Pup}» до НІП «{npc:Kibler}».",
  ["5340bd46"] = "Поверніть предмет «{item:Nostro's Compendium of Dragon Slaying}» у місцевість «{zone:Athenaeum}».",
  ["543a7da9"] = "Доставте предмет «{item:Unloaded Zapper}» і 5 зразків «{item:Atal'ai Haze}» до НІП «{npc:Larion}» у місцевості «{zone:Marshal's Refuge}».",
  ["547c1c53"] = "Знайдіть НІП «{npc:Prate Cloudseer}» у локації «{zone:Thousand Needles}».",
  ["54a27fc1"] = "Принесіть 1 купку «{item:Kraul Guano}» до НІП «{npc:Master Apothecary Faranell}» у місті «{zone:Undercity}».",
  ["554dccd3"] = "Вступний крок до завдання «{quest:Scarab Shells}».",
  ["557bb950"] = "Здолайте «{npc:Twilight Fanatic}»: 8, «{npc:Twilight Corrupter}»: 8 і «{npc:Twilight Champion}»: 8 у місцевості «{zone:Twilight's Shroud}» для НІП «{npc:Da'grosh}».",
  ["561142d6"] = "Вирушайте до вказаного міста й знайдіть загадкового торговця.",
  ["564edb5b"] = "Ці гриби також можна зібрати поза підземеллям.",
  ["5657e515"] = "Здобудьте предмет «{item:Grimy Key}» для НІП «{npc:Magus Wordeen Voidglare}» у місцевості «{zone:Tarren Mill}».",
  ["5681a0d7"] = "Принесіть «{item:Star Ruby}»: 2 шт., «{item:Gold Bar}»: 20 шт. і «{item:Truesilver Bar}»: 10 шт. до НІП «{npc:Gloom'rel}», потім покладіть їх у «{zone:Spectral Chalice}» у місцевості «{zone:Summoners' Tomb}».",
  ["5693156a"] = "Будь-яка істота в підземеллі «{zone:Maraudon}» може залишити потрібні для завдання предмети.",
  ["56b7f8b1"] = "Віднесіть цей предмет до НІП «{npc:Gregan Brewspewer}» у локації «{zone:Feralas}».",
  ["56c2ba1f"] = "Здобудьте особливий корм для духа коня. Схоже, такий корм можна дістати в НІП «{npc:Merideth Carlson}» у місцевості «{zone:Southshore}». Вирушайте до підземелля «{zone:Dire Maul}» у локації «{zone:Feralas}» і вбийте боса «{npc:Tendris Warpwood}». Так ви звільните духа «{npc:Ancient Equine Spirit}». Нагодуйте його особливим кормом, щоб заспокоїти. Насамкінець віддайте йому предмет «{item:Arcanite Barding}», щоб він його благословив.",
  ["56d45047"] = "Припаси лежать у печерах, що ведуть до входу в підземелля «{zone:Deadmines}».",
  ["56d70720"] = "Убийте 12 НІП «{npc:Meadowsbrook Farmhand}», а потім поверніться до НІП «{npc:Krom'rosh}» з доповіддю про успіх.",
  ["56f7ec57"] = "Убийте боса «{npc:Princess Theradras}» у внутрішній печері.",
  ["570bcc98"] = "Використайте предмет «{item:Divination Scryer}» у центрі підвалу місцевості «{zone:The Great Ossuary}» у підземеллі «{zone:Scholomance}». З’являться духи, з якими треба битися. Здолавши їх, ви викличете боса «{npc:Death Knight Darkreaver}»; здолайте його. Принесіть предмет «{item:Darkreaver's Head}» до НІП «{npc:Eldrun Stormbreaker}» у місті «{zone:Ironforge}».",
  ["57133c49"] = "Завдання паладина на бойового коня. Зачистьте підвал боса «{npc:Rattlegore}» у місцевості «{zone:The Great Ossuary}», використайте предмет «{item:Divination Scryer}» і здолайте духів та боса «{npc:Death Knight Darkreaver}».",
  ["574ed63d"] = "Убийте «{npc:Black Broodling}»: 15, «{npc:Black Dragonspawn}»: 10, «{npc:Black Wyrmkin}»: 4 і «{npc:Black Drake}»: 1. Виконавши завдання, поверніться до НІП «{npc:Helendis Riverhorn}».",
  ["57b5457e"] = "Здолайте «{npc:Twilight Fanatic}»: 8, «{npc:Twilight Corrupter}»: 8 і «{npc:Twilight Champion}»: 8 у місцевості «{zone:Twilight's Shroud}» для НІП «{npc:Sergeant Riftan}».",
  ["57d3fd50"] = "Виконується разом із завданням «{quest:Scraps of Knowledge}».",
  ["58ae0b48"] = "Для класів «Воїн» і «Паладин». Потім Лідрос дає завдання «{quest:The Forging of Quel'Serrar}», яке завершується в рейді «{zone:Onyxia's Lair}».",
  ["58c2b633"] = "Покажіть предмет «{item:Document Box}» НІП «{npc:Nazgrel}».",
  ["58d2cec4"] = "Щоб це завдання стало доступним, потрібне завдання «{quest:The Dark Iron War}».",
  ["58d7b2d3"] = "Вам треба здобути предмет «{item:Blood of the Black Dragon Champion}» у боса «{npc:General Drakkisath}». Він перебуває у своїй тронній залі в глибині підземелля «{zone:Blackrock Spire}».",
  ["590370bc"] = "Вирушайте до НІП «{npc:Gershala Nightwhisper}» у місцевості «{zone:Auberdine}» (локація «{zone:Darkshore}»).",
  ["5977be67"] = "Вирушайте на схід, до місцевості «{zone:Corin's Crossing}», і перебийте ворогів, що заполонили містечко. Менш ніж за 10 хвилин зберіть «{item:Living Rot}»: 7 шт. За допомогою предмета із цього завдання розітріть «{item:Living Rot}» на предмет «{item:Coagulated Rot}».",
  ["59999a7d"] = "Віднесіть предмет «{item:Arcanite Barding}» до НІП «{npc:Lord Grayson Shadowbreaker}» у місті «{zone:Stormwind}», щоб він його оглянув.",
  ["5a15910d"] = "Заберіть щоденник НІП «{npc:Apothecary Berard}» у місцевості «{zone:Pyrewood Village}» і віднесіть його до НІП «{npc:Apothecary Renferrel}» у місцевості «{zone:The Sepulcher}».",
  ["5a24a7ac"] = "Предмет «{item:The Heart of the Mountain}» лежить у сейфі сховища після Темних хранителів.",
  ["5a288fe0"] = "Зберіть «{item:Voodoo-Infused Artifact}»: 10 шт. з місцевих піратів у підземеллі «{zone:The Drowned City}».",
  ["5a746a60"] = "Останній крок. Шукайте НІП у місцевості «{zone:The Greymane Wall}» на півдні локації «{zone:Silverpine Forest}». Нагорода — предмет.",
  ["5aaaa774"] = "Зберіть «{item:Brinescale Trident}»: 10 шт. із місцевих застрільників.",
  ["5ac4b825"] = "Убийте боса «{npc:Alzzin the Wildshaper}», підберіть біля лози предмет «{item:Felvine Shard}» і запечатайте його в предметі «{item:Reliquary of Purity}».",
  ["5b02e249"] = "Вирушайте до підземелля «{zone:Blackrock Depths}» і здобудьте «{item:Essence of the Elements}»: 10 шт. Спершу варто обшукати големів і їхніх творців. Ви пам’ятаєте, що Вівіан Лаґрейв також бурмотіла щось про елементалів.",
  ["5ba85f4f"] = "Віднесіть незавершений предмет «{item:Banner of Provocation}» до НІП «{npc:Falrin Treeshaper}» у бібліотеці в підземеллі «{zone:Dire Maul}».",
  ["5bafb465"] = "Убийте 15 розлючених привидів і 10 змучених душ, а потім упокойте дух Анвілмара.",
  ["5cee7ac8"] = "Вкладіть предмет «{item:Grime-Encrusted Object}» у «{zone:The Sparklematic 5200}» разом із трьома срібними монетами, щоб запустити машину.",
  ["5cefb5cd"] = "Принесіть предмети «{item:Brilliant Gold Ring}», «{item:Silver Bar}», «{item:Moss Agate}» і 30 срібних монет до НІП «{npc:Nogg}» у місті «{zone:Orgrimmar}».",
  ["5d42db96"] = "Зачекайте, поки НІП «{npc:Velarok Windblade}» виконає завдання «{quest:The Torch of Retribution}».",
  ["5d595bdc"] = "Зачекайте, поки «{npc:Jordan Stilwell}» викує для вас зброю.",
  ["5d8d2fc2"] = "Поговоріть з НІП «{npc:Nazeer Bloodpike}» у місцевості «{zone:Brackenwall Village}».",
  ["5d8f97c4"] = "Пошукайте цінне намисто на розкопках «{zone:Uldaman}» і принесіть його до НІП «{npc:Dran Droffers}» у місті «{zone:Orgrimmar}». Намисто може бути пошкоджене.",
  ["5db68d9b"] = "Увійдіть до місця розкопок у локації «{zone:Wetlands}» і принесіть «{item:Thicket Raptor Meat}»: 4 шт.",
  ["5dccee55"] = "Знайдіть у Монастирі предмет «{item:Mythology of the Titans}» і принесіть його до НІП «{npc:Librarian Mae Paledust}» у місті «{zone:Ironforge}».",
  ["5e1b868c"] = "Поговоріть з НІП у місцевості «{zone:Aerie Peak}» у локації «{zone:The Hinterlands}».",
  ["5e535bed"] = "Супроводьте свого в’язня, НІП «{npc:Grark Lorkrub}», через локації «{zone:Burning Steppes}» і «{zone:Blackrock Mountain}» до локації «{zone:Searing Gorge}». Ви пам’ятаєте, як НІП «{npc:Lexlort}» казав, що його люди чекатимуть на тому боці, щоб узяти Ґрарка під варту. Також потрібно буде віддати предмет «{item:Thorium Shackles}» НІП «{npc:Lexlort}».",
  ["5e98533d"] = "Вислухайте історію НІП «{npc:Velarok Windblade}».",
  ["5ea9224f"] = "Віднесіть відбитки табличок до НІП «{npc:Master Gadrin}» у поселенні «{zone:Sen'jin Village}» (локація «{zone:Durotar}»).",
  ["5edf9d54"] = "Вирушайте до підземелля «{zone:Blackrock Depths}» і знищте мерзенних загарбників! НІП «{npc:Warlord Goretooth}» хоче, щоб ви вбили «{npc:Anvilrage Guardsman}»: 15, «{npc:Anvilrage Warden}»: 10 і «{npc:Anvilrage Footman}»: 5. Виконавши завдання, поверніться до нього.",
  ["5f1b3a6f"] = "Захистіть командира Ґор’шака.",
  ["5f880f5b"] = "Предмет «{item:Rough Dynamite}» можна створити, виміняти або купити на аукціоні.",
  ["5faf754c"] = "Вирушайте до підземелля «{zone:Krol'dok Stronghold}» і убийте вказаного ворога.",
  ["5fbf9fb7"] = "Вирушайте до підземелля «{zone:Blackrock Depths}» і вбийте боса «{npc:General Angerforge}»! Виконавши завдання, поверніться до НІП «{npc:Warlord Goretooth}».",
  ["6004cf96"] = "Крок у підземеллі «{zone:Razorfen Kraul}».",
  ["611dc182"] = "Подивіться, як «{npc:Ott}» кує ваш клинок.",
  ["6136fa12"] = "Поговоріть з НІП «{npc:Sputtervalve}» у місцевості «{zone:Ratchet}» про предмет «{item:Glowing Shard}», а потім доставте його до НІП «{npc:Falla Sagewind}» на вершину гори над підземеллям «{zone:Wailing Caverns}».",
  ["61847503"] = "Завдання чорнокнижника на коня жаху. Коли бос «{npc:Immol'thar}» загине, проведіть ритуал у його в’язниці з предметами «{item:J'eevee's Jar}», «{item:Black Lodestone}» і «{item:Xorothian Glyphs}». Візьміть із собою уламки душі.",
  ["61d67d20"] = "Знайдіть чотирьох зрадників-Відступників у таборі «{zone:Lordamere Internment Camp}», заберіть їхні артефакти і поверніться до НІП «{npc:Magus Wordeen Voidglare}».",
  ["623b193d"] = "Вирушайте до міста «{zone:Stormwind City}» і дійдіть до міської брами. Поговоріть із НІП «{npc:Squire Rowe}», щоб він повідомив НІП «{npc:Marshal Windsor}» про ваше прибуття.",
  ["623f186e"] = "Здобудьте предмет «{item:Lorgalis Manuscript}» у підземеллі «{zone:Blackfathom Deeps}».",
  ["629c3a8e"] = "Знайдіть НІП «{npc:Rethiel the Greenwarden}» у локації «{zone:Wetlands}».",
  ["62f3a5b7"] = "Не дайте принцесі Мойрі загинути й поговоріть із нею після смерті імператора Даґрана Тауріссана. Її завдання відправить вас по нагороду назад до Маґні.",
  ["631ef992"] = "Віднесіть предмет «{item:Hammertoe's Amulet}» до НІП «{npc:Historian Karnik}» у місті «{zone:Ironforge}».",
  ["633ca92d"] = "Вирушайте до підземелля «{zone:Blackrock Depths}» і знайдіть НІП «{npc:Kharan Mighthammer}». Король згадував, що Карана тримають там у полоні, — можливо, варто пошукати в’язницю.",
  ["63bc30f5"] = "Наповніть її флакон у зловісному ставку в місцевості «{zone:Eldreth Row}» у західному крилі підземелля «{zone:Dire Maul}»; також принесіть 1 предмет «{item:Enchanted Thorium Bar}» і «{item:Crystal Restore}»: 5 шт.\n\nНеобов’язкове вступне завдання:",
  ["63c1cf33"] = "Зберіть «{item:Thicket Raptor Hide}»: 4 шт. і віднесіть їх до НІП «{npc:James Halloran}» у місцевості «{zone:Menethil Harbor}».",
  ["63e269c1"] = "Цей камінь також пов’язаний з необов’язковою битвою з босом «{npc:Baron Aquanis}».",
  ["6418fa2c"] = "Здобудьте «{item:Plagued Flesh Sample}»: 20 шт. у підземеллі «{zone:Stratholme}» і поверніть їх до НІП «{npc:Betina Bigglezink}». Вам здається, що такий зразок плоті може мати будь-яка істота в підземеллі «{zone:Stratholme}».",
  ["6482a7cc"] = "Класове завдання розбійника. Лист від замовника приходить на 20-му рівні в столиці; візьміть замовлення в схованці біля місцевості «{zone:Pyrewood Village}». Залиште вільне місце в сумці.",
  ["6482b68c"] = "Вислухайте НІП «{npc:Thrall}».",
  ["64874ca7"] = "Огляньте «{zone:Altar of Hakkar}» у підвалі храму. Видає НІП «{npc:Marvon Rivetseeker}» після завдання, у якому треба знайти предмет «{item:Stone Circle}».",
  ["64921528"] = "Здобудьте джерело енергії з найпотужнішого конструкта, якого знайдете в підземеллі «{zone:Uldaman}», і доставте його до НІП «{npc:Talvash del Kissel}» у місті «{zone:Ironforge}».",
  ["649e13be"] = "Вирушайте до локації «{zone:Burning Steppes}» і знайдіть НІП «{npc:Grark Lorkrub}». Ви пам’ятаєте, як НІП «{npc:Lexlort}» казав, що востаннє його бачили у величезній фортеці Блекрок. Знайшовши НІП «{npc:Grark Lorkrub}», скуйте його предметом «{item:Thorium Shackles}» і відведіть через місцевість «{zone:Blackrock Mountain}» до локації «{zone:Searing Gorge}». НІП «{npc:Lexlort}» чекатиме з людьми на тому боці, щоб узяти Ґрарка під варту.",
  ["64d45695"] = "Використайте шкуру й деревне вугілля, щоб зробити відбитки чотирьох табличок у підземеллі «{zone:The Drowned City}».",
  ["64e64c5b"] = "Поговоріть з НІП «{npc:Historian Karnik}».",
  ["64f8ec2e"] = "Вирушайте до підземелля «{zone:Blackrock Spire}» і зберіть очі «{item:Black Dragonspawn Eye}»: 20 шт. Виконавши завдання, поверніться до НІП «{npc:Myranda the Hag}».",
  ["64ff75cd"] = "Віднесіть цей лист до НІП «{npc:Raleigh the Devout}» у місцевості «{zone:Southshore}».",
  ["65409b20"] = "Зустріньте НІП у місцевості «{zone:Cathedral of Light}» у місті «{zone:Stormwind}».",
  ["6596d341"] = "Знайдіть НІП «{npc:Magister Kirandis}» у храмі в місцевості «{zone:Shen'dralas}».",
  ["65e15f65"] = "Принесіть предмет «{item:Libram of Protection}», 1 предмет «{item:Pristine Black Diamond}», «{item:Large Brilliant Shard}»: 2 шт. і 1 предмет «{item:Frayed Abomination Stitching}» НІП «{npc:Lorekeeper Lydros}» у підземеллі «{zone:Dire Maul}», щоб отримати предмет «{item:Arcanum of Protection}».",
  ["660e16d4"] = "Скористайтеся підказками із записки, щоб дізнатися, де шукати магічні компоненти для ритуалу. Для цього вам знадобиться допомога союзників.",
  ["661812d5"] = "Дослідіть розколину під місцевістю «{zone:The Forgotten Pools}».",
  ["664d98d0"] = "Книга класу «Друїд». Клацніть на книгу, щоб почати завдання.",
  ["66af59f3"] = "Принесіть пера вуду до НІП «{npc:Bath'rah the Windwatcher}».",
  ["66c59edb"] = "Убийте ворога в підземеллі «{zone:Krol'dok Stronghold}» і здобудьте будь-які цінні відомості.",
  ["67269279"] = "Знайдіть предмет «{item:Torn Letter}» (гравець повідомляє, що він випадає з НІП «{npc:Burning Blade Summoner}») і поверніться до НІП «{npc:Katherine the Pure}».",
  ["67740207"] = "Застосуйте видану клітку до істоти «{npc:Bloodaxe Worg Pup}» у лігві воргів.",
  ["67d47031"] = "Убийте боса «{npc:Golem Lord Argelmach}» заради його голови й зберіть «{item:Intact Elemental Core}»: 10 шт. з конструктів, що його охороняють.",
  ["67d48f30"] = "Принесіть 1 купку «{item:Kraul Guano}» від місцевих кажанів до НІП «{npc:Master Apothecary Faranell}».",
  ["67d96388"] = "Предмет «{item:Lorgalis Manuscript}» лежить у скрині під водою в місцевості «{zone:The Pool of Ask'ar}», у північній ніші одразу за кімнатою черепахи «{npc:Ghamoo-ra}».",
  ["68b211b7"] = "Бічний тунель з нежиттю розташований перед порталом підземелля.",
  ["6922d65c"] = "Хто видає завдання, ще не підтверджено. Попереднє завдання: віднести предмет «{item:Savage Coast Report Bundle}» до НІП «{npc:Loremaster Dibbs}».",
  ["6970add4"] = "Предмет «{item:Darkstone Tablet}» лежить на землі в місцевості «{zone:The Rookery}».\n\nНеобов’язкове вступне завдання:",
  ["6a123f4b"] = "Знищте «{npc:Undead Ravager}»: 30, потім поверніться до НІП «{npc:Brother Anton}» у місцевості «{zone:Nijel's Point}».",
  ["6a565255"] = "Ідіть за обгорілою запискою з локації «{zone:The Barrens}» до місця-двійника: обгорілих решток на фермі «{zone:Alexston Farmstead}» у локації «{zone:Westfall}».",
  ["6a5aacfb"] = "Знайдіть кузню в підземеллі «{zone:Deadmines}» і закладіть поруч із нею предмет «{item:Extra-Destructive Explosives}».",
  ["6a6ba1cf"] = "Принесіть предмет «{item:Lethtendris's Web}» до НІП «{npc:Talo Thornhoof}» у місцевості «{zone:Camp Mojache}» у локації «{zone:Feralas}».",
  ["6aeed6b3"] = "Виконується разом з іншим із двох завдань НІП «{npc:Sergeant Yohwa}» («{quest:The Second Rebellion}» і «{quest:Bad Medicine}»); НІП «{npc:Brother Nimetz}» видає завдання «{quest:Kurzen's Mystery}», щойно здано обидва.",
  ["6b3687e2"] = "Нагорода від цього НІП — щит «{item:Furen's Favor}».",
  ["6baae808"] = "Одиночне замовлення: виконайте його самі, поза будь-якою групою.",
  ["6bb17222"] = "Якщо погоджуєтеся допомогти НІП «{npc:Belnistrasz}», поговоріть із ним знову й поверніть йому камінь клятви, який він вам дав.",
  ["6bb232df"] = "Зберіть «{item:Miners' Union Card}»: 4 шт. із шахтарів-нежиті в тунелях поза підземеллям.",
  ["6bc317c7"] = "НІП «{npc:Archbishop Benedictus}» просить вас убити боса «{npc:Amnennar the Coldbringer}» у підземеллі «{zone:Razorfen Downs}».",
  ["6bdbd351"] = "Принесіть предмет «{item:Libram of Focus}», 1 предмет «{item:Pristine Black Diamond}», «{item:Large Brilliant Shard}»: 4 шт. і «{item:Skin of Shadow}»: 2 шт. НІП «{npc:Lorekeeper Lydros}» у підземеллі «{zone:Dire Maul}», щоб отримати предмет «{item:Arcanum of Focus}».",
  ["6be86e6f"] = "НІП «{npc:Atal'ai Exile}» у локації «{zone:The Hinterlands}» хоче отримати предмет «{item:Head of Jammal'an}».",
  ["6c64b9c1"] = "Зберіть «{item:Twisted Fire Totem}»: 5 шт., «{item:Twisted Earth Totem}»: 5 шт., «{item:Twisted Air Totem}»: 5 шт. і «{item:Twisted Water Totem}»: 5 шт. для НІП «{npc:Veyric Thunderhame}» у локації «{zone:Arathi Highlands}».",
  ["6d0bc59a"] = "Принесіть предмет «{item:Divino-matic Rod}» до НІП «{npc:Chief Engineer Bilgewhizzle}» у місті «{zone:Gadgetzan}».",
  ["6d252ccc"] = "Вирушайте до підземелля «{zone:Blackrock Spire}» і зберіть яйця «{item:Spire Spider Egg}»: 15 шт. для НІП «{npc:Kibler}». Судячи з усього, ці яйця можна знайти біля павуків.",
  ["6e0be194"] = "Зберіть «{item:Twisted Fire Totem}»: 5 шт., «{item:Twisted Earth Totem}»: 5 шт., «{item:Twisted Air Totem}»: 5 шт. і «{item:Twisted Water Totem}»: 5 шт. та здайте їх НІП «{npc:Prate Cloudseer}» у локації «{zone:Thousand Needles}».",
  ["6e43ad47"] = "Убийте цього ворога на місці розкопок і принесіть його кореневе ядро до НІП «{npc:Rethiel the Greenwarden}» у локації «{zone:Wetlands}».",
  ["6e676b08"] = "Заберіть предмет «{item:Arcane Shard}» у боса «{npc:Morphaz}» і поверніться до НІП «{npc:Archmage Xylem}».",
  ["6ea61767"] = "Вислухайте розповідь НІП «{npc:Kharan Mighthammer}».",
  ["6f84d0a5"] = "Завдання шамана. Зачистьте підвал боса «{npc:Rattlegore}», використайте предмет із завдання і здолайте боса «{npc:Death Knight Darkreaver}»; принесіть його голову.",
  ["6fc97641"] = "Вирушайте до підземелля «{zone:Blackrock Spire}» і знищте джерело загрози від воргів. Коли ви йшли від Гелендіса, він вигукнув ім’я: «{npc:Halycon}». Так орки називають ворга, про якого йдеться.",
  ["6fd32769"] = "Класове завдання розбійника після завдання «{quest:The Horn of Xelthos}»; наступний лист від «C» (близько 30-го рівня) знову відправляє вас до схованки. Носіть предмет «{item:Scarlet Initiate's Uniform}» у кожному крилі: непомітність або атака знімають його.",
  ["700ee3f0"] = "Розбийте три бочонки в коморі місцевості «{zone:The Grim Guzzler}», щоб з’явилися НІП «{npc:Hurley Blackbreath}» і його охоронці.\n\nНеобов’язкове вступне завдання:",
  ["701919f4"] = "Принесіть предмет «{item:Enchanted Thorium Bar}», предмет «{item:Crystal Restore}»: 5 шт. і предмет «{item:Vial of Dire Water}» до НІП «{npc:Aurora Skycaller}» біля місцевості «{zone:Northpass Tower}» у локації «{zone:Eastern Plaguelands}».",
  ["70724029"] = "Наздоганяйте біса «{npc:Pusillin}» крилом і говоріть із ним, доки він не почне бій, тоді вбийте його заради книги. З нього також випадає предмет «{item:Crescent Key}».",
  ["70b9469b"] = "Убийте 7 цих істот у локації «{zone:Blasted Lands}» і поверніться до НІП «{npc:Fallen Hero of the Horde}».",
  ["7120b67f"] = "Вирушайте до підземелля «{zone:Blackmaw Hold}» на континенті «{zone:Kalimdor}» і здобудьте предмет «{item:Reliquary of Tyr}».",
  ["714f2fc5"] = "Убийте «{npc:Mosshide Gnoll}»: 15 і «{npc:Mosshide Mongrel}»: 10, а потім поверніться до НІП «{npc:Rethiel the Greenwarden}».",
  ["716cdbc6"] = "Вирушайте до місцевості «{zone:Wyrmbog}» у локації «{zone:Dustwallow Marsh}» і знайдіть лігво «{zone:Emberstrife's Den}». Усередині надягніть предмет «{item:Amulet of Draconic Subversion}» і поговоріть із дрейком «{npc:Emberstrife}».",
  ["71b9fd46"] = "Спершу вивчіть вміння, що виявляє пастки: щоб пройти випробування, достатньо пройти повз скриню-пастку в печерному проході до маєтку (цього навчає й НІП «{npc:Fahrad}»).",
  ["71d4cfba"] = "Класове завдання паладина для нежиті й тауренів. У цьому підземеллі предмет «{item:Enchanted Silver Ingot}» лежить на столі в кімнаті НІП «{npc:Archmage Arugal}», після того як ви його вб’єте. Інші частини: «{item:Whitestone Oak Lumber}» («{zone:The Deadmines}») і «{item:Purified Kor Gem}» («{zone:Blackfathom Deeps}»).",
  ["71dee56e"] = "Книга класу «Мисливець». Клацніть на книгу, щоб почати завдання.",
  ["71df3fcd"] = "Поговоріть з НІП «{npc:Master Gadrin}» у селищі «{zone:Sen'jin Village}».",
  ["724362f2"] = "Довгий ланцюжок завдань: частина сюжету паладина Альянсу.",
  ["726cb520"] = "Поверніться до НІП «{npc:Ashe Amberhall}» у фортеці «{zone:Farholde Keep}».",
  ["729fd9d1"] = "Покладіть предмет «{item:Essence of Eranikus}» у «{zone:Essence Font}» у цьому лігві в підземеллі «{zone:Sunken Temple}».",
  ["730d0c48"] = "Класове завдання паладина для нежиті й тауренів. У цьому підземеллі предмет «{item:Corrupted Kor Gem}» випадає з блекфатомських морських відьом усередині, а також із блекфатомських жриць припливу та оракулів біля входу в локації «{zone:Ashenvale}», щойно ви візьмете відповідне завдання у НІП «{npc:Ulric Frostveil}» у місцевості «{zone:Zoram'gar Outpost}». Він і очищає камінь. Інші частини: «{item:Whitestone Oak Lumber}» («{zone:The Deadmines}») і «{item:Enchanted Silver Ingot}» («{zone:Shadowfang Keep}»).",
  ["730f4010"] = "Супроводьте НІП «{npc:Belnistrasz}» до ідола свинобразів у підземеллі «{zone:Razorfen Downs}». Захищайте НІП «{npc:Belnistrasz}», поки він виконує ритуал, щоб вимкнути ідол.",
  ["74195c4a"] = "Принесіть голову ворога до НІП «{npc:Gatekeeper Rageroar}» у місцевості «{zone:Ursolan}».",
  ["743d8b86"] = "Це ланцюжок завдань із кроком у підземеллі «{zone:Shadowfang Keep}»",
  ["745ee317"] = "Вступний крок до завдання «{quest:The Essence of Aku'Mai}».",
  ["749ffba2"] = "Принесіть предмет «{item:Razorflank's Heart}» до НІП «{npc:Auld Stonespire}» у місті «{zone:Thunder Bluff}».",
  ["74fa8b27"] = "Здобудьте предмет «{item:Fragment of the Firelands}» у НІП «{npc:Magmus}» у підземеллі «{zone:Blackrock Depths}» для НІП «{npc:Alaana Stormwalker}» у локації «{zone:Mulgore}».",
  ["751d858f"] = "Принесіть «{item:Buzzard Gizzard}»: 5 шт., «{item:Crag Coyote Fang}»: 10 шт. і «{item:Rock Elemental Shard}»: 5 шт. до НІП «{npc:Jarkal Mossmeld}» у місцевості «{zone:Kargath}» (локація «{zone:Badlands}»).",
  ["75de357e"] = "Після здачі відкривається «{item:Eye of Mugg}» (НІП «{npc:Demar Brant}»).",
  ["7603eb60"] = "Здобудьте в локації «{zone:Badlands}» реагенти, потрібні НІП «{npc:Ghak Healtouch}», потім поверніться до нього в місцевість «{zone:Thelsamar}».",
  ["76c61bc8"] = "Заберіть предмет «{item:Thistlenettle's Badge}» у НІП «{npc:Foreman Thistlenettle}» у бічному тунелі з нежиттю.",
  ["76f6858a"] = "Віднесіть предмет «{item:Grimtotem Satchel}» до НІП «{npc:Rahauro}» у місті «{zone:Thunder Bluff}».",
  ["77091e57"] = "Це виконується ПОЗА підземеллям.",
  ["77155b02"] = "Ця скриня стоїть у місцевості «{zone:The Rookery}». Потім здайте завдання «{quest:Delivery to Ridgewell}» НІП «{npc:Count Remington Ridgewell}» у місцевості «{zone:Stormwind Keep}», щоб отримати нагороду.\n\nНеобов’язкове вступне завдання:",
  ["773a0ce1"] = "Убийте боса «{npc:Archivist Galford}» у місцевості «{zone:The Scarlet Bastion}» і спаліть архіви.",
  ["77dcb222"] = "Супроводьте НІП «{npc:Willix the Importer}» до виходу з підземелля «{zone:Razorfen Kraul}».",
  ["78c75ddb"] = "Поговоріть з НІП «{npc:Gorn One Eye}» у місцевості «{zone:Timbermaw Hold}» і попросіть його надіслати підкріплення.",
  ["794a143b"] = "Поговоріть із НІП «{npc:Eitrigg}» у місті «{zone:Orgrimmar}». Обговоривши справи з НІП «{npc:Eitrigg}», попросіть поради в НІП «{npc:Thrall}». Ви пригадуєте, що бачили НІП «{npc:Eitrigg}» у покоях НІП «{npc:Thrall}».",
  ["79906f0f"] = "Дочекайтеся, поки НІП «{npc:Talvash del Kissel}» завершить відновлення намиста, потім заберіть його.",
  ["7a8c404c"] = "Ключ із цього завдання відкриває короткий шлях до останнього боса.",
  ["7ab82d04"] = "Поговоріть з НІП «{npc:Scooty}» у місцевості «{zone:Booty Bay}».",
  ["7ae370b0"] = "Здобудьте предмет «{item:Zarla's Journal}» з глибин підземелля «{zone:Alcaz Prison}».",
  ["7ae558a2"] = "Принесіть самоцвіти Кобрана, Анакондри, Пайтаса й Серпентіса до НІП «{npc:Nara Wildmane}».",
  ["7aec49fd"] = "Перший крок обов’язкового ланцюжка Братства Дефіас.",
  ["7af16034"] = "Здайте предмет «{item:Thorium Brotherhood Contract}» НІП «{npc:Lokhtos Darkbargainer}», якщо хочете отримати креслення Сульфуронового молота.",
  ["7bd8b66f"] = "Дізнайтеся фразу до скрині цього НІП, потім поверніться до нього.",
  ["7c2f50ac"] = "Класове завдання мага. Лідрос перебуває в залі «{zone:Athenaeum}» (північне/західне крило); предмет «{item:Hydrospawn Essence}» випадає з боса «{npc:Hydrospawn}» у східному крилі. Нагорода: заклинання мага, ранг 7.",
  ["7c479dc0"] = "Принесіть предмет «{item:Undamaged Venom Sac}» до НІП «{npc:Apothecary Lydon}» у місцевості «{zone:Tarren Mill}».",
  ["7c5d0e7c"] = "Версія для Альянсу. Коли здасте завдання НІП «{npc:Sergeant Riftan}», ви отримаєте наступне, і відкриється ще одне.",
  ["7d4afb6e"] = "Дослідіть місцевість «{zone:Fenris Keep}» на півночі й спробуйте знайти зниклого члена загону Земляного Кільця.",
  ["7d4e1c53"] = "Потрібна нейтральна репутація зі «{zone:Timbermaw Hold}».",
  ["7d4ecac9"] = "Нагорі вежі поговоріть із вартовим біля НІП «{npc:Archmage Tervosh}» (у маскуванні він схожий на вас) і замініть його; не підходьте близько до Джайни, бо вона розвіє маскування. Після завершення ви якийсь час не зможете рухатися: скористайтеся командою виходу з транспорту.",
  ["7dc2123a"] = "НІП «{npc:Master Apothecary Faranell}» у місті «{zone:Undercity}» потрібно «{item:Heart of Zeal}»: 20 шт.",
  ["7e0c35c2"] = "Наповніть флакон «{item:Coated Cerulean Vial}» у басейні з помаранчевими кристалами в підземеллі «{zone:Maraudon}». Використайте «{item:Filled Cerulean Vial}» на ліанах, щоб змусити зіпсованих паростків «{npc:Noxxious Scion}» вийти. Зцілте 8 рослин, убиваючи паростків «{npc:Noxxious Scion}», потім поверніться до НІП «{npc:Vark Battlescar}» у селищі «{zone:Shadowprey Village}».",
  ["7e15c78d"] = "Вирушайте на північ, до підземелля «{zone:Stratholme}». Обшукайте ящики з припасами, розкидані містом, і здобудьте «{item:Stratholme Holy Water}»: 5 шт. Коли зберете досить благословенної рідини, поверніться до НІП «{npc:Leonid Barthalomew the Revered}».",
  ["7e338389"] = "Убийте боса «{npc:Archmage Arugal}» і принесіть його голову до НІП «{npc:Dalar Dawnweaver}».",
  ["7e48f3e9"] = "Знайдіть Лозу Скверни в підземеллі «{zone:Dire Maul}» і здобудьте з неї уламок. Найімовірніше, отримати його вдасться лише після загибелі боса «{npc:Alzzin the Wildshaper}». Надійно запечатайте уламок у предметі «{item:Reliquary of Purity}» і віднесіть до НІП «{npc:Rabine Saturna}» у місцевості «{zone:Nighthaven}» (локація «{zone:Moonglade}»).",
  ["7e5e8fbc"] = "Знайдіть шлях до міста «{zone:Dalaran}» уздовж озера «{zone:Lordamere Lake}».",
  ["7e9c632f"] = "Принесіть предмет «{item:Tiara of the Deep}» до НІП «{npc:Tabetha}» у локації «{zone:Dustwallow Marsh}».",
  ["7efb687b"] = "Принесіть предмети «{item:Azerothian Diamond}» і «{item:Pristine Black Diamond}» до НІП «{npc:Lord Grayson Shadowbreaker}» у місті «{zone:Stormwind}».",
  ["7f0c47fa"] = "Тут немає завдання, яке можна взяти. Просто вбийте й заберіть здобич.",
  ["7f5ebaf1"] = "Перший обов’язковий крок перед завданням «{quest:Horrors in the Highland}».",
  ["7fab4322"] = "Останній крок. Нагорода — предмет «{item:Fire Hardened Hauberk}».",
  ["800fdc5b"] = "Убийте вартових усіх п’яти пілонів, потім боса «{npc:Immol'thar}», потім боса «{npc:Prince Tortheldrin}». Поверніться до Прадавнього Шен’дралара, візьміть «{zone:Treasure of the Shen'dralar}» і відкрийте скриню під сходами бібліотеки, щоб отримати нагороду.",
  ["805360f9"] = "Отримайте лист, що починає це завдання. Орда: у тренера розбійників виберіть варіант, де ви просите лист. Альянс: у начальника розвідки в місті «{zone:Stormwind}».",
  ["808bbf07"] = "Скористайтеся предметом «{item:SI:7 Disguise Kit}», щоб підслухати Джайну та її найближче оточення у місцевій вежі магів.",
  ["808bf750"] = "Убийте ворога «{npc:Demon of the Orb}», потім поговоріть з НІП «{npc:Tabetha}».",
  ["80dc2e99"] = "Вирушайте до підземелля «{zone:Stratholme}» і вбийте боса «{npc:Ramstein the Gorger}». Заберіть його голову на згадку для Натаноса.",
  ["813a705b"] = "Зійдіться з НІП «{npc:Ulathek}», потім принесіть предмет «{item:The Traitor's Heart}» до НІП «{npc:Lord Banehollow}» у місцевості «{zone:Jaedenar}».",
  ["814fe4fe"] = "Принесіть «{item:Thick Leather}»: 4 шт. і «{item:Iron Bar}»: 12 шт. до НІП «{npc:Alphonse Dumas}».",
  ["816ad1d5"] = "Це завдання виконується поза підземеллям, в озері під містом «{zone:Undercity}».",
  ["81803436"] = "Допоможіть НІП «{npc:Celebras the Redeemed}», поки він створює «{item:Scepter of Celebras}». Поговоріть із ним, коли ритуал завершиться.",
  ["81dff696"] = "Дослідіть місцевість «{zone:Shen'dralas}», щоб знайти інші пілони, схожі на той, що ви знайшли.",
  ["81e185ef"] = "Принесіть 6 зразків предмета «{item:Lake Creeper Moss}», 6 зразків предмета «{item:Lake Skulker Moss}» і предмет «{item:Hardened Tumor}» до НІП «{npc:Master Apothecary Faranell}» у місті «{zone:Undercity}».",
  ["82028be7"] = "Зберіть «{item:Corrupted Brain Stem}»: 8 шт. з істот у підземеллі «{zone:Blackfathom Deeps}».",
  ["82224e3e"] = "Супроводьте НІП «{npc:The Defias Traitor}», доки він не покаже схованку Дефіасів, а потім поверніться до НІП «{npc:Gryan Stoutmantle}».",
  ["822b8215"] = "Принесіть «{item:Altered Snapjaw Shell}»: 8 шт. до НІП «{npc:Tonga Runetotem}» у місцевості «{zone:The Crossroads}».",
  ["8238c063"] = "Принесіть «{item:Bolt of Runecloth}»: 4 шт., «{item:Rugged Leather}»: 8 шт., «{item:Rune Thread}»: 2 шт. і 1 предмет «{item:Ogre Tannin}» (кошик на верхньому ярусі за Нотом). Пошийте всі потрібні костюми й вивчіть викрійку до того, як звільните Нота, бо він піде.",
  ["82546669"] = "Убийте «{npc:Dalaran Summoner}»: 6 і «{npc:Elemental Slave}»: 12, потім поверніться до НІП «{npc:Magus Wordeen Voidglare}» у місцевості «{zone:Tarren Mill}».",
  ["82de239e"] = "Останній крок ланцюжка «{quest:The Defias Brotherhood}» у підземеллі; спершу виконайте попередні кроки.",
  ["830341dd"] = "Виконується разом із завданням «{quest:Food for the Taking}».",
  ["831c813a"] = "Цих ворогів усередині може не вистачити, щоб виконати завдання за один прохід.",
  ["8344ec9e"] = "Знайдіть зниклих огрів у печерах під місцевістю «{zone:Sunnyglade}» для НІП «{npc:Clubtoe}».",
  ["83477c39"] = "Віднесіть предмет «{item:Wiley's Note}» до НІП «{npc:Master Mathias Shaw}» у місті «{zone:Stormwind}».",
  ["84895a94"] = "Бос «{npc:Herod}» — у Зброярні; бос «Локсі» — у крилі «{zone:Library}»; боси «Моґрейн» і «Вайтмейн» — у Соборі.",
  ["852e682d"] = "Необов’язкове вступне завдання:",
  ["85bdaa81"] = "Місцевість «{zone:Caverns of Time}» у пустелі Танаріс охороняє дрейк «{npc:Chronalis}», нащадок Ноздорму. Знищте його й віднесіть його череп до дрейка «{npc:Emberstrife}».",
  ["864a8a9e"] = "Знайдіть НІП «{npc:Da'grosh}» у пагорбах на захід від місцевості «{zone:Rog'mar}».",
  ["86f04fd9"] = "Це завдання виконують у бібліотеці, в зоні порталів Альянсу в місті «{zone:Dalaran}» з доповнення «Гнів Короля-Ліча».",
  ["871584d4"] = "Принесіть «{item:Thick Leather}»: 4 шт. і «{item:Iron Bar}»: 12 шт. НІП «{npc:Kreza Darkthorn}».",
  ["87c5b19b"] = "Принесіть злитки «{item:Arcanite Bar}»: 3 шт. до НІП «Ґорзікі» в локації «{zone:Burning Steppes}».",
  ["87ccd849"] = "Поясні сумки випадають із дворфів Темного Заліза в Глибинах Блекрок.",
  ["87f69356"] = "Знайдіть предмет «{item:Tablet of Will}» і поверніть його до НІП «{npc:Advisor Belgrum}» у місті «{zone:Ironforge}».",
  ["87fea959"] = "Відчиніть його камеру предметом «{item:Prison Cell Key}» від НІП «{npc:High Interrogator Gerstahn}», а потім захистіть його.",
  ["88183d28"] = "Повторюване, після першої здачі торбинок.",
  ["883baf73"] = "Принесіть предмети «{item:Claws of the Great Bear}» і «{item:Tusks of the Unbroken}» до НІП «{npc:Ogtinc}» у локації «{zone:Azshara}».",
  ["88842f24"] = "Принесіть загалом «{item:Voodoo Feathers}»: 6 шт. від тролів у затонулому храмі.",
  ["89d48181"] = "Необов’язковий вступ до версії Альянсу завдання «{quest:Blackfathom Villainy}»: здайте його до того, як візьмете завдання «{quest:Blackfathom Villainy}», інакше його вже не вдасться виконати.",
  ["89e0ae81"] = "Класове завдання друїда. Предмет «{item:Putrid Vine}» випадає з боса «{npc:Atal'alarion}» у підвалі храму.\n\nНеобов’язкове вступне завдання:",
  ["89e16b9c"] = "Щоб дістатися фігурки, стрибайте на різьблені голови греблі з боку локації «{zone:Wetlands}». Для Орди дістатися туди складно.",
  ["89f0e428"] = "Потім цей НІП приймає ще торбинки як повторюване завдання («{zone:Timbermaw Hold}» +100).",
  ["8a27329d"] = "Купіть зілля у НІП «Ґорзікі» в локації «{zone:Burning Steppes}». Скористайтеся зіллями, щоб пройти через місцевість «{zone:Jaedenar}», і поговоріть із НІП «{npc:Lord Banehollow}».",
  ["8a706267"] = "За водоспадом «{zone:Earth Song Falls}» знайдіть залу з яскраво-білими кристалами, яку охороняють велетні. Візьміть «{item:An'she's Radiance}» з кристала біля найвищої частини зали. Нагорода: 300 репутації із Земляним Кільцем і 200 репутації з містом «{zone:Thunder Bluff}».",
  ["8ac68f3b"] = "Вступний крок до завдання «{quest:The Hidden Chamber}».",
  ["8ad499ec"] = "На платформі боса «{npc:Electrocutioner 6000}».",
  ["8b7985df"] = "Здолайте боса «{npc:Overlord Kilgar}» у місцевості «{zone:Twilight's Shroud}» і принесіть його голову НІП «{npc:Da'grosh}».",
  ["8bab4d72"] = "Усередині підземелля, у приміщенні «{zone:Dormitory}».",
  ["8bdfe1eb"] = "Книга класу «Чорнокнижник». Клацніть на книгу, щоб почати завдання.",
  ["8bf10d57"] = "Знищте дрейка-чемпіона зеленого роду, Сомнуса. Заберіть його череп і віднесіть до дрейка «{npc:Emberstrife}».",
  ["8c1605c9"] = "П’ята й шоста таблички Мош’ару лежать на ділянці тролів Тліючого Шипа. Далі йдуть завдання «{quest:Confront Yeh'kinya}» і «{quest:The Hand of Rastakhan}».",
  ["8d5d2360"] = "Принесіть 20 флаконів «{item:Troll Temper}» до НІП «{npc:Trenton Lighthammer}» у місті «{zone:Gadgetzan}».",
  ["8dac25e4"] = "Вирушайте до підземелля «{zone:Dire Maul}» і знайдіть біса «{npc:Pusillin}». Будь-якими засобами переконайте біса «{npc:Pusillin}» віддати вам його книгу. Якщо здобудете предмет «{item:Book of Incantations}», поверніться до НІП «{npc:Azj'Tordin}» у місцевості «{zone:Lariss Pavilion}» у локації «{zone:Feralas}».",
  ["8dc2fe41"] = "Принесіть предмет «{item:Case of Blood}» до НІП «{npc:Gorzeeki Wildeyes}» у локації «{zone:Burning Steppes}».",
  ["8e796e8f"] = "Вирушайте до локації «{zone:Arathi Highlands}», до руїн Стромґарда. Обшукайте Стромґард і знайдіть предмет «{item:Keepsake of Remembrance}». Якщо знайдете його, поверніться з ним до НІП «{npc:Magistrate Marduke}».",
  ["8ef12254"] = "Знайдіть боса «{npc:Ras Frostwhisper}» у підземеллі «{zone:Scholomance}». Знайшовши його, застосуйте предмет «{item:Soulbound Keepsake}» до його неживої подоби. Якщо вдасться знову зробити його смертним, убийте його і заберіть предмет «{item:Human Head of Ras Frostwhisper}». Віднесіть голову до НІП «{npc:Magistrate Marduke}».",
  ["8f22866e"] = "Доставте предмет «{item:Necklace and Gem Salvage}» до НІП «{npc:Dran Droffers}» у місті «{zone:Orgrimmar}».",
  ["8f96a5ad"] = "Зберіть предмети «{item:Spells of Shadow}» та «Заклинання з Нижнього Світу» у підземеллі «{zone:Ragefire Chasm}».",
  ["90dfd92a"] = "Іде після завдання «{quest:Speak with Shoni}».",
  ["90eabe36"] = "Прийміть завдання «%s» раніше за завдання «%s». Якщо завдання «%s» зникне, покиньте завдання «%s», і воно з’явиться знову.",
  ["90ec4468"] = "У серці підземелля «{zone:Blackrock Spire}» ви знайдете боса «{npc:Mother Smolderweb}». Вступіть із нею в бій і дайте їй вас отруїти. Поверніться до НІП «{npc:Ragged John}», поки отрута діє, щоб він міг вас «подоїти».",
  ["90ff4db9"] = "Класове завдання чорнокнижника. Потрібен предмет «{item:Voodoo Feathers}»: 2 бурштинові, 2 сині й 2 зелені пера від шести тролів-охоронців: НІП «{npc:Gasher}», «{npc:Mijan}», «{npc:Zolo}», «{npc:Hukku}», «{npc:Zul'Lor}» і «{npc:Loro}».",
  ["910d2d0d"] = "Зберіть матеріали, потрібні НІП «{npc:Furen Longbeard}», і принесіть їх йому в місто «{zone:Stormwind}».",
  ["9113f162"] = "Іде після версії завдання «{quest:Allegiance to the Old Gods}», що починається з предмета «{item:Damp Note}».",
  ["91c108db"] = "Принесіть тканину «Рунна Тканина»: 40 шт., злитки «{item:Arcanite Bar}»: 6 шт., предмет «{item:Arthas' Tears}»: 10 шт., флакони «{item:Stratholme Holy Water}»: 5 шт. і 150 золотих до НІП «{npc:Grimand Elmore}» у кварталі «{zone:Dwarven District}» міста «{zone:Stormwind}».",
  ["924e8ed0"] = "Віднесіть предмет «{item:Eye of the Tempest}» до НІП «{npc:Bath'rah the Windwatcher}» у локації «{zone:Alterac Mountains}».",
  ["92b137f2"] = "Убийте «{npc:Deviate Ravager}»: 7, «{npc:Deviate Viper}»: 7, «{npc:Deviate Shambler}»: 7 і «{npc:Deviate Dreadfang}»: 7.",
  ["92de6d08"] = "Принесіть 30 пляшок предмета «{item:Raging Beast's Blood}» до НІП «{npc:Mor'zul Bloodbringer}» у локації «{zone:Burning Steppes}».",
  ["92fb4f6f"] = "Вирушайте до Каплиці Надії Світла в локації «{zone:Eastern Plaguelands}» і розшукайте НІП «{npc:Leonid Barthalomew the Revered}». Покажіть йому предмет «{item:Keepsake of Remembrance}» і розкажіть усе, що дізналися.",
  ["93425648"] = "Убийте його вбивцю — НІП «{npc:Murdaloc}». Убийте «{npc:Stonevault Bonesnapper}»: 12. Поверніться з доповіддю до НІП «{npc:Prospector Ironband}» у локації «{zone:Loch Modan}».",
  ["935270be"] = "Використайте предмет «{item:Empty Leaden Collection Phial}» на живій істоті «{npc:Irradiated Invader}» або «{npc:Irradiated Pillager}», потім віднесіть повну колбу до НІП «{npc:Ozzie Togglevolt}».",
  ["93716ddc"] = "Здобудьте предмет «{item:Ichor of Undeath}» для НІП «{npc:Ogtinc}» у локації «{zone:Azshara}». НІП «{npc:Ogtinc}» живе на вершині скель на північний схід від місцевості «{zone:Ruins of Eldarath}».",
  ["9396c367"] = "Частина ланцюжка, що починається із завдання «{quest:The Unsent Letter}» від НІП «{npc:Edwin VanCleef}» у підземеллі «{zone:The Deadmines}».",
  ["939fa536"] = "Знайдіть предмет «{item:Eye of Bhossca}» у підземеллі «{zone:Scarlet Monastery}». Потім віднесіть його до схованки «C» біля місцевості «{zone:Pyrewood Village}». Виконати це потрібно самотужки.",
  ["943e2ff8"] = "Поговоріть із Кам’яним вартовим і дізнайтеся, які давні знання він береже. Дізнавшись їх, активуйте «{zone:The Discs of Norgannon}».",
  ["947f71fa"] = "Знайдіть і вбийте боса «{npc:Golem Lord Argelmach}». Принесіть його голову до Лотвіла. Також потрібно зібрати «{item:Intact Elemental Core}»: 10 шт. з големів-шаленців і конструктів-войовників, що охороняють Арґельмаха.",
  ["94ea9dea"] = "Вирушайте до місцевості «{zone:Lakeshire}» і доставте предмет «{item:Helendis Riverhorn's Letter}» до НІП «{npc:Magistrate Solomon}».",
  ["94eb5d66"] = "Прочитайте предмет «{item:Warosh's Scroll}». Принесіть предмет «{item:Warosh's Mojo}» до НІП «{npc:Warosh}».",
  ["94fabbc4"] = "Вирушайте до підземелля «{zone:Dire Maul}» і вбийте водяного елементаля «{npc:Hydrospawn}». Поверніться з предметом «{item:Hydrospawn Essence}» до НІП «{npc:Lorekeeper Lydros}» у залі «{zone:Athenaeum}».",
  ["95045ff0"] = "Принесіть предмет «{item:Ancient Egg}» до НІП «{npc:Yeh'kinya}» у локації «{zone:Tanaris}».",
  ["958e536b"] = "Знайдіть предмет «{item:Bijou's Belongings}» і поверніть його власниці. Хай щастить!",
  ["95d1ea21"] = "Принесіть «{item:Red Leather Bandana}»: 15 шт. НІП «{npc:Scout Galiaan}» у місцевості «{zone:Sentinel Hill}».",
  ["967f8c87"] = "Вступний крок до завдання «{quest:Destroy Morphaz}».",
  ["974136dd"] = "Переконайте шахтаря-НІП «{npc:Twilight's Hammer}» у місцевості «{zone:Sunnyglade}» розкрити свої таємниці.",
  ["977c8222"] = "Вступний крок до завдання «{quest:Blood of Morphaz}».",
  ["9798e3e8"] = "Супроводьте НІП «{npc:Marshal Windsor}» через в’язницю. Спершу зачистіть патрулі й переконайтеся, що всі готові, перш ніж почати.",
  ["97a5e99d"] = "Поговоріть із НІП «{npc:Mor'zul Bloodbringer}» у локації «{zone:Burning Steppes}».",
  ["97ddc342"] = "Торба випадає з боса «{npc:Jandice Barov}».",
  ["98276b20"] = "«{npc:Kirin Tor}» пускають до міста «{zone:Dalaran}» лише видатних відвідувачів.",
  ["989df5ad"] = "Використайте предмет «{item:Blood of Innocents}» біля жаровні на ґанку підземелля «{zone:Scholomance}». Нагорода — предмет «{item:Spectral Essence}».",
  ["99284977"] = "Увійдіть до підземелля «{zone:Alcaz Prison}», убийте 15 солдатів і 8 чарівниць Страшазів та принесіть голову їхньої ватажки тому, хто дав вам це завдання.",
  ["995d92b5"] = "Потім віднесіть предмет «{item:Bijou's Reconnaissance Report}» до НІП «{npc:Lexlort}» у місцевості «{zone:Kargath}», щоб отримати нагороду.",
  ["99a5d306"] = "Принесіть «{item:Skullsplitter Fetish}»: 4 шт. до НІП «{npc:Brother Nimetz}».",
  ["99d9c98d"] = "На першій великій розвилці на три шляхи оберіть правий тунель, ідіть ним угору до глухого кута, а тоді зайдіть до невеликої бічної кімнати ліворуч. Там взаємодійте з тілом НІП «Маур».",
  ["9a28394f"] = "Предмет «{item:Mana Sieve}» — на верхньому поверсі великого храму. Візьміть 8 мани з таємних сфер довкола «{zone:Shen'dralas}», потім використайте частини пілонів, по 4 мани на кожен пілон.",
  ["9a7b57a1"] = "Поговоріть з НІП «{npc:Duthorian Rall}» у місті «{zone:Stormwind}».",
  ["9b140f0f"] = "Принесіть предмет «{item:Razorflank's Medallion}» до НІП «{npc:Falfindel Waywarder}» у місцевості «{zone:Thalanaar}».",
  ["9b3952ca"] = "Принесіть предмет «{item:Damp Note}» до НІП «{npc:Je'neu Sancrea}» у локації «{zone:Ashenvale}».",
  ["9b6cae57"] = "Доставте предмет «{item:Rexxar's Testament}» до НІП «{npc:Myranda the Hag}» у локації «{zone:Western Plaguelands}».",
  ["9b77a0e3"] = "Підпаліть північну, південну, східну і західну сторожові вежі, використавши предмет «{item:Torch of Retribution}» усередині кожної будівлі.",
  ["9b8d4442"] = "Поговоріть з НІП «{npc:Prate Cloudseer}» у локації «{zone:Thousand Needles}».",
  ["9ba7c810"] = "Елітне, рівень 40: зберіть групу. Біля парових озер у локації «{zone:Thousand Needles}» станьте в коло рун і використайте предмет «{item:Corrupted Totems}». Наступають хвилі елементалів, потім елітний шипогрив і «{npc:Ravaging Tempest}», з якого випадає предмет «{item:Eye of the Tempest}» для кожного шамана із цим завданням. Орда: хто видає завдання, ще не підтверджено; дивіться журнал завдань.",
  ["9bbb35d6"] = "Здобудьте в Монастирі предмет «{item:Compendium of the Fallen}» і поверніться до НІП «{npc:Sage Truthseeker}» у місті «{zone:Thunder Bluff}».",
  ["9bf77380"] = "Схоже, ви натрапили на щось, що НІП «{npc:Marshal Windsor}» захоче побачити. Можливо, надія все ж є.",
  ["9c38c98a"] = "Принесіть «{item:Encoded Fragment}»: 10 шт. до НІП «{npc:Archmage Xylem}» у локації «{zone:Azshara}».",
  ["9c43b12c"] = "Застосуйте предмет «{item:Eggscilloscope Prototype}» до яйця в місцевості «{zone:The Rookery}».",
  ["9c49f4df"] = "Вступний крок до завдання «{quest:Ramstein}».",
  ["9c9a3641"] = "Необов’язкове вступне завдання для Альянсу, що веде до завдання «{quest:Researching the Corruption}».",
  ["9ca373d8"] = "Принесіть «{item:Heart of Zeal}»: 20 шт. з підземелля «{zone:Scarlet Monastery}» до НІП «{npc:Master Apothecary Faranell}».",
  ["9cb23a05"] = "Принесіть предмет «{item:Filled Egg of Hakkar}» до НІП «{npc:Yeh'kinya}» у локації «{zone:Tanaris}».",
  ["9cbd7bb5"] = "Поверніть книгу її законним власникам.",
  ["9cd73439"] = "Поговоріть із НІП «{npc:Mordent Evenshade}» у місцевості «{zone:Shen'dralas}» про кристали, які ви полагодили.",
  ["9cd86341"] = "Остання умова перед кроком завдання «{quest:The Defias Brotherhood}» у підземеллі.",
  ["9d68c087"] = "Принесіть першу й другу таблички Мош’ару до НІП «{npc:Yeh'kinya}» у локації «{zone:Tanaris}».",
  ["9dd67542"] = "Убийте ворга «{npc:Halycon}», ватажку зграї воргів клану Кривавої Сокири.",
  ["9e2451d0"] = "Ковальство. Принесіть предмет «{item:Sulfuron Ingot}» (випадає з боса рейду «{zone:Molten Core}») до торговця в місцевості «{zone:The Grim Guzzler}», щоб отримати контракт, а потім здайте його назад за креслення «{item:Sulfuron Hammer}».",
  ["9e3cb4ca"] = "Залізьте на «{zone:Thoradin's Wall}» з воза з боку «{zone:Hillsbrad}» (87.3, 49.6), пройдіть крізь кімнату в стіні й подивіться назовні праворуч: там висить торба.",
  ["9e5080dc"] = "Убийте боса «{npc:Princess Theradras}» і поверніться до НІП «{npc:Selendra}» біля селища «{zone:Shadowprey Village}» у локації «{zone:Desolace}».",
  ["9e50b7e8"] = "Ідіть прямо на північ від табору, підніміться на пагорб і зістрибніть із його краю до «{zone:Mound of Dirt}». Обережно, дивіться під ноги.",
  ["9e8dcd3a"] = "Заберіть предмет «{item:Highly Toxic Strain}» у цього ворога.",
  ["9ea46061"] = "Сапфір випадає з боса «{npc:Grimlok}».",
  ["9ee56a8b"] = "Поверніться з предметом «{item:Blessed Arcanite Barding}» до НІП «{npc:Lord Grayson Shadowbreaker}» у місті «{zone:Stormwind}».",
  ["9efa83e0"] = "Знайдіть предмет «{item:Treshala's Pendant}» і поверніть його до НІП «{npc:Treshala Fallowbrook}» у місті «{zone:Darnassus}».",
  ["9f439b60"] = "Убийте «{npc:Plagued Hatchling}»: 20, а потім поверніться до НІП «{npc:Betina Bigglezink}» у місцевості «{zone:Light's Hope Chapel}».",
  ["9f54a924"] = "Поговоріть з НІП «{npc:Tabetha}» у локації «{zone:Dustwallow Marsh}».",
  ["9f5fdc4d"] = "Виконайте завдання «{quest:The Dark Iron War}», щоб відкрити завдання «{quest:The Fury Runs Deep}».",
  ["9f9967f5"] = "Доставте предмет «{item:Titan Relic}» до НІП «{npc:Muln Earthfury}» у місцевості «{zone:Skywatcher Plateau}» на північному заході локації «{zone:Mulgore}».",
  ["9fbf0335"] = "Зберіть «{item:Enchanted Coral}»: 6 шт. і віднесіть їх до НІП «{npc:Archmage Xylem}».",
  ["a03d3c01"] = "Прочитайте знайдений журнал, дослідіть приховану кімнату, потім поверніться з доповіддю до НІП «{npc:Prospector Stormpike}».",
  ["a07fb8e9"] = "Віднесіть предмет «{item:Titan Relic}» до місцевості «{zone:Elder Rise}» у місті «{zone:Thunder Bluff}» і пошукайте того, хто розповість про нього більше.",
  ["a0bcde1d"] = "Поговоріть із дружнім НІП «{npc:Captain Kromcrush}», коли станете королем Ґордоків. Предмет «{item:Gauntlet of Gordok Might}» лежить у скрині біля НІП «{npc:Prince Tortheldrin}» у західному крилі підземелля «{zone:Dire Maul}».",
  ["a0e901ba"] = "Здобудьте «{item:Rough Dynamite}»: 10 шт. (створіть, виміняйте або купіть на аукціоні), а потім поверніться до НІП «{npc:Sprite Jumpsprocket}» у районі «{zone:Dwarven District}» міста «{zone:Stormwind}».",
  ["a19833ba"] = "Вступний крок до завдання «{quest:Lethtendris's Web}».",
  ["a1abfc41"] = "Медальйон лежить у скрині біля боса в місцевості «{zone:The Scarlet Bastion}». Віддайте його НІП «{npc:Aurius}» у каплиці до бою з бароном.",
  ["a1b2cab2"] = "НІП «{npc:Awbee}» — поранений синій дракон біля шляху до арени після Ренда. Скористайтеся руною глибоко в печері «{zone:Mazthoril}», щоб дістатися до НІП «{npc:Haleh}».",
  ["a1c33064"] = "Поговоріть з НІП «{npc:Katherine the Pure}» у «{zone:Cathedral of Light}» в місті «{zone:Stormwind}».",
  ["a1e1f492"] = "Принесіть предмет «{item:Inert Scourgestone}» до НІП «Командир Ашлам Валорфіст» у місцевості «{zone:Chillwind Point}».",
  ["a23b8090"] = "Убийте боса «{npc:Dextren Ward}» у підземеллі «{zone:The Stockade}» і віднесіть його руку до НІП «{npc:Councilman Millstipe}».",
  ["a2615301"] = "Завдання паладина на бойового коня. Убийте боса «{npc:Tendris Warpwood}», потім нагодуйте духа «{npc:Ancient Equine Spirit}» і віддайте йому предмет «{item:Arcanite Barding}». Візьміть із собою предмет «{item:Manna-Enriched Horse Feed}» від НІП «{npc:Merideth Carlson}» у місцевості «{zone:Southshore}».",
  ["a2c2914e"] = "Розбійники: виконайте завдання «{quest:The Manor, Ravenholdt}», «{quest:The Horn of Xelthos}» і «{quest:The Eye of Bhossca}». На 45-му рівні поверніться до великого міста по лист від НІП «{npc:Fahrad}». У місцевості «{zone:Ravenholdt Manor}» виконайте наступне завдання ланцюжка, поговоривши з НІП «{npc:Fahrad}»; тоді він пропонує «{item:Talisman of Kazdor}». До підземелля «{zone:Zul'Farrak}» заходьте самі.",
  ["a2e7e73b"] = "Табличка лежить в одному зі сховищ у місцевості «{zone:Reliquary of Kings}», у залі останнього боса. Відчиніть сховища й взаємодійте з табличкою, перш ніж покинути підземелля.",
  ["a2f7c539"] = "Здолайте боса «{npc:Charlga Razorflank}» у підземеллі «{zone:Razorfen Kraul}» і зберіть відомості про плани шипогривів.",
  ["a31fda8a"] = "Обшукайте сумку, що лежить під іншою сумкою, біля «{zone:Thoradin's Wall}».",
  ["a36d7b13"] = "Дослідіть води місцевості «{zone:The Forgotten Pools}» на північний захід від місцевості «{zone:The Crossroads}», а потім поверніться з доповіддю.",
  ["a3741ba4"] = "Енергетичні камені також можуть випадати з елітних дворфів поза підземеллям.",
  ["a397bbb2"] = "Принесіть павутину до НІП «{npc:Latronicus Moonspear}» у місцевості «{zone:Feathermoon Stronghold}» у локації «{zone:Feralas}».",
  ["a3c82037"] = "НІП «Ніру» перебуває в місцевості «{zone:Cleft of Shadow}» біля входу до підземелля «{zone:Ragefire Chasm}».",
  ["a3e10cac"] = "Принесіть предмет «{item:Satchel of Mementos}» замовникові.",
  ["a3f04017"] = "Упокойте дух загиблого.",
  ["a40f5d31"] = "Інші пілони: на сході, у точці 73, 23 (там ще таємні елементалі, і вас скидають із верхової тварини) і на півдні, у точці 47, 78, усередині великої будівлі в місцевості «{zone:Shen'dralas}».",
  ["a43f1c2a"] = "Віднесіть послання до НІП «{npc:Katherine the Pure}» у «{zone:Cathedral of Light}» в місті «{zone:Stormwind}».",
  ["a4fbfe2d"] = "Поговоріть з НІП «{npc:Commander Ashlam Valorfist}» у місцевості «{zone:Chillwind Point}».",
  ["a5263287"] = "Убийте босів «{npc:High Inquisitor Whitemane}», «{npc:Scarlet Commander Mograine}», «{npc:Herod}», «{npc:Scarlet Champion}» і «{npc:Houndmaster Loksey}», а потім поверніться з доповіддю до НІП «{npc:Raleigh the Devout}» у місцевості «{zone:Southshore}».",
  ["a608498f"] = "Поверніться до підземелля «{zone:Blackrock Depths}» і врятуйте НІП «{npc:Princess Moira Bronzebeard}» з лихих пазурів НІП «{npc:Emperor Dagran Thaurissan}».",
  ["a66f96da"] = "Зберіть гриби: 8 шт. і «{item:Gorishi Sting}»: 8 шт. та поверніться до НІП «{npc:Torwa Pathfinder}» у локації «{zone:Un'Goro Crater}».",
  ["a6810893"] = "Доступне, коли наступний лист від «C» надійде вам у столиці.",
  ["a73b2074"] = "Бригадир перебуває в тунелях перед порталом підземелля.",
  ["a7554640"] = "Убийте «{npc:Farholde Priest}»: 8 і «{npc:Farholde Scout}»: 12 на південь від річки.",
  ["a75f1984"] = "Вступний крок до завдання «{quest:The Darkstone Tablet}».",
  ["a7665b10"] = "Використайте предмет «{item:Divination Scryer}» у самому серці підвалу місцевості «{zone:The Great Ossuary}» в підземеллі «{zone:Scholomance}». Так ви викличете духів, з якими маєте битися. Перемога над ними викличе боса «{npc:Death Knight Darkreaver}»; здолайте його. Принесіть предмет «{item:Darkreaver's Head}» до НІП «{npc:Sagorne Creststrider}» у місцевості «{zone:Valley of Wisdom}» у місті «{zone:Orgrimmar}».",
  ["a7d1421e"] = "Знайдіть потрібну сумку біля «{zone:Thoradin's Wall}», між «{zone:Hillsbrad Foothills}» і «{zone:Arathi Highlands}».",
  ["a801f89b"] = "Підніміться стежкою на північний схід від місцевості «{zone:Sun Rock Retreat}» (50.9, 52.3) до покинутого табору; потрібний предмет лежить на ящику. За бажанням: розпаліть багаття посеред табору за допомогою предмета «{item:Simple Wood}» і предмета із цього завдання («{quest:Rekindle}»).",
  ["a834d46a"] = "Знайдіть предмет «{item:Gordok Shackle Key}» на ограх крила Ґордоків і звільніть ним НІП «{npc:Knot Thimblejack}».",
  ["a87e81d8"] = "Принесіть предмет «{item:Nekrum's Medallion}» до НІП «{npc:Thadius Grimshade}» у локації «{zone:Blasted Lands}».",
  ["a88fe72d"] = "Покладіть вибухівку біля кузні в підземеллі «{zone:Deadmines}».",
  ["a8d34914"] = "Потрібне перед завданням «{quest:Gnomer-gooooone!}».",
  ["a8d67620"] = "Принесіть до НІП «{npc:Thun'grim Firegaze}» «{item:Smoky Iron Ingot}»: 15 шт., «{item:Powdered Azurite}»: 10 шт., «{item:Iron Bar}»: 10 шт. і предмет «{item:Vial of Phlogiston}».",
  ["a8f2c153"] = "Потрібен ланцюжок завдань про оази локації «{zone:The Barrens}». Виконайте завдання «{quest:The Barrens Oases}», «{quest:The Forgotten Pools}», «{quest:The Stagnant Oasis}» і «{quest:Altered Beings}», потім «{quest:Hamuul Runetotem}» і «{quest:Nara Wildmane}» — тоді стане доступним завдання «{quest:Leaders of the Fang}».",
  ["a8f3bbea"] = "Принесіть предмет «{item:Infernal Orb}» до НІП «{npc:Tabetha}» у локації «{zone:Dustwallow Marsh}».",
  ["a91839d9"] = "Зберіть «{item:Twilight Charm}»: 25 шт. із сутінкових тіньомантів і неофітів у місцевості «{zone:Sunnyglade}» для НІП «{npc:Ashe Amberhall}» у фортеці «{zone:Farholde Keep}».",
  ["a96509b8"] = "Віднесіть обручку НІП «{npc:Vorrel Sengutz}» (від НІП «{npc:Nancy Vishas}») до НІП «{npc:Monika Sengutz}» у місцевості «{zone:Tarren Mill}».",
  ["a967f5bf"] = "Убийте боса «{npc:Emperor Dagran Thaurissan}» і звільніть НІП «{npc:Princess Moira Bronzebeard}» від його лихих чарів.",
  ["a978de8f"] = "Потрібне перед завданням «{quest:Hearts of Zeal}».",
  ["a9de45d4"] = "Зберіть «{item:Cracked Sentry Core}»: 6 шт. з конструктів у місті «{zone:Dalaran}».",
  ["aa3482db"] = "Віднесіть книгу «{item:Rituals of Power}» до НІП «{npc:Tabetha}» у локації «{zone:Dustwallow Marsh}».",
  ["aa7102e2"] = "Зберіть «{item:Sapphire of Aku'Mai}»: 20 шт. у підземеллі «{zone:Blackfathom Deeps}».",
  ["aaaf7d3c"] = "Принесіть предмет «{item:Frozen Eggs}» до НІП «{npc:Betina Bigglezink}».",
  ["aaf64cbb"] = "Класове завдання паладина. Потрібен предмет «{item:Voodoo Feathers}»: 2 бурштинові, 2 сині й 2 зелені пера від шести тролів-охоронців: НІП «{npc:Gasher}», «{npc:Mijan}», «{npc:Zolo}», «{npc:Hukku}», «{npc:Zul'Lor}» і «{npc:Loro}».\n\nНеобов’язкове вступне завдання:",
  ["ab06ef5f"] = "Виконайте це завдання до вбивства останнього боса.",
  ["ab3b1089"] = "Це може вдатися не з першого разу: використовуйте його на живому слизні, доки не вийде.",
  ["ab602a26"] = "Чотири купчі: «{zone:Southshore}» — у першій великій залі, «{zone:Tarren Mill}» — перед дитинчатами, «{zone:Brill}» — біля боса «{npc:Ras Frostwhisper}», «{zone:Caer Darrow}» — біля боса «{npc:Lord Alexei Barov}». Наступне завдання посилає вас убити брата-суперника.",
  ["ac04846c"] = "Вступний крок до завдання «{quest:Agmond's Fate}».",
  ["ac134e38"] = "Здобудьте предмет «{item:The Coldbringer's Eye}» у підземеллі «{zone:Razorfen Downs}».",
  ["ac2823b0"] = "Віднесіть предмет «{item:I'lalai Fetish}» до НІП «{npc:Abra Cadabra}» у місті «{zone:Dalaran}».",
  ["ac2dd012"] = "Потрібне перед завданням «{quest:The Only Cure is More Green Glow}».",
  ["ac4c8908"] = "Поговоріть з НІП «{npc:Ragnar Thunderbrew}».",
  ["ac8f504d"] = "Знайдіть первісного творця розбитого намиста, щоб дізнатися, скільки воно може коштувати.",
  ["acd91e7e"] = "Принесіть предмет «{item:Felnok's Package}» до НІП «{npc:Tinkee Steamboil}» у локації «{zone:Burning Steppes}».",
  ["ad1f28b5"] = "Зберіть «{item:I'lalai Fetish}»: 5 шт. з тролів у підземеллі «{zone:The Drowned City}».",
  ["ad7d19e3"] = "Вирушайте до каменоломні в місцевості «{zone:Blackrock Mountain}» і вбийте боса «{npc:Overmaster Pyron}». Виконавши доручення, поверніться до НІП «{npc:Thunderheart}».",
  ["adc91988"] = "Нежить не може взяти це завдання",
  ["ae1712f9"] = "Поверніть предмет «{item:Exorcism Censer}» до НІП «{npc:Lord Grayson Shadowbreaker}» у місті «{zone:Stormwind}».",
  ["ae72c421"] = "Заберіть «99-Річний Портвейн» у НІП «{npc:Mad Magglish}» у підземеллі «{zone:Wailing Caverns}».",
  ["ae80f690"] = "Бос «{npc:Herod}» — у Зброярні; бос «Локсі» — у крилі «{zone:Library}»; боси «Моґрейн» і «Вайтмейн» — у Соборі.\n\nНеобов’язкове вступне завдання:",
  ["aeda38f9"] = "Убийте босів «{npc:High Inquisitor Whitemane}», «{npc:Scarlet Commander Mograine}», «{npc:Herod}», «{npc:Scarlet Champion}» і «{npc:Houndmaster Loksey}», а потім поверніться з доповіддю до НІП «{npc:Varimathras}» у місті «{zone:Undercity}».",
  ["aedb0a8f"] = "Починає наступний ланцюжок, що продовжується завданням «{quest:Bazil Thredd}».",
  ["aef96495"] = "Вступний крок до завдання «{quest:The Green Drake}».",
  ["af02bf05"] = "Принесіть предмет «{item:Broodling Essence}»: 8 шт. і Драко-Інкарцинатрикс 900 до НІП «{npc:Tinkee Steamboil}» у місцевості «{zone:Flame Crest}» у локації «{zone:Burning Steppes}».",
  ["af9b1ca8"] = "Принесіть «Книгу Ура» з підземелля «{zone:Shadowfang Keep}» до НІП «{npc:Keeper Bel'dugur}».",
  ["b053d240"] = "Класове завдання паладина для людей і дворфів. У цьому підземеллі предмет «{item:Jordan's Smithing Hammer}» береться з об’єкта у дворі. Інші частини: «{item:Whitestone Oak Lumber}» («{zone:The Deadmines}»), «Самоцвіт Кор» («{zone:Blackfathom Deeps}») і партія руди НІП «Джордан» («{zone:Loch Modan}»).",
  ["b0603492"] = "Завдання паладина Альянсу. Як його відкрити: «{item:Bloody Missive}», потім завдання про пошуки (у місцевості «{zone:Emerald Sanctuary}» спершу взаємодійте з конем, а тоді йдіть за його слідом), потім поговоріть із конем і з НІП у локації «{zone:Felwood}»: той видає завдання про особливі матеріали. Його частини — з «{zone:Felwood}», «{zone:Maraudon}», «{zone:Blackrock Depths}» і «{zone:Hillsbrad Foothills}».",
  ["b08e28c7"] = "Вирушайте до підземелля «{zone:Stratholme}» у північній частині Чумних Земель. У місцевості «{zone:The Scarlet Bastion}» ви знайдете потрібну картину, заховану за іншою картиною, на якій зображено два місяці нашого світу. Поверніть картину до НІП «{npc:Tirion Fordring}».",
  ["b0feff0a"] = "Останній крок. Виберіть один із предметів: «{item:Rage of the Storm}», «{item:Lightning's Grasp}» або «{item:Tidebringer's Claw}».",
  ["b10b01a0"] = "Зберіть «{item:Shadowshard Fragment}»: 10 шт. у підземеллі «{zone:Maraudon}» і віднесіть їх до НІП «{npc:Uthel'nay}» у місті «{zone:Orgrimmar}».",
  ["b226ce3e"] = "Ковальство 270 (бронник). Застосуйте предмет «{item:Blood Stained Pike}» до трупа Ґоралука і підберіть поруч предмет «{item:Unforged Rune Covered Breastplate}».",
  ["b27ad31e"] = "Знайдіть НІП «{npc:Argent Guard Thaelrid}» у підземеллі «{zone:Blackfathom Deeps}».",
  ["b2a161b0"] = "Вирушайте до місцевості «{zone:Grim Batol}» і вистежте дрейка «{npc:Axtroz}», чемпіона червоного роду. Знищте його й заберіть його череп. Віднесіть череп до дрейка «{npc:Emberstrife}».",
  ["b2b5e874"] = "Знайдіть і вбийте «{npc:Duskwing}». Заберіть із тіла предмет «{item:Patch of Duskwing's Fur}» і поверніть його до НІП «{npc:Nathanos Blightcaller}». Кажуть, цей звір блукає околицями неподалік.",
  ["b2c863ba"] = "Вступний крок до завдання «{quest:Ribbly Screwspigot}».",
  ["b33ea3d8"] = "Після здачі відкриваються «{item:Eye of Mugg}» (НІП «{npc:Krom'rosh}») і «{item:Tome of Twilight}» (НІП «{npc:Tran'gul}»).",
  ["b34a8e50"] = "Віднесіть предмет «{item:Hammertoe's Amulet}» до НІП «{npc:Prospector Ryedol}» у локації «{zone:Badlands}».",
  ["b34b9f52"] = "Правильно дайте відповідь на запитання НІП, а потім знову поговоріть із ним.",
  ["b3536134"] = "Повертає віддалений детонатор інженерові.",
  ["b3b3a0f4"] = "Знайдіть предмети «{item:Totem of Ursoc}» і «{item:Totem of Ursol}» у підземеллі «{zone:Blackmaw Hold}». Потім поверніть їх до НІП у місцевості «{zone:Ursolan}».",
  ["b3ffe2a5"] = "Поговоріть з цим НІП, щоб дізнатися більше.",
  ["b401ea67"] = "Поговоріть з НІП «{npc:Fallen Hero of the Horde}» біля входу до локації «{zone:Blasted Lands}».",
  ["b5018d68"] = "Знайдіть спосіб очистити предмет «{item:Grime-Encrusted Ring}» від бруду за допомогою «{zone:The Sparklematic 5200}».",
  ["b5201f38"] = "Вирушайте до підземелля «{zone:Blackrock Spire}» і вбийте боса «{npc:Warchief Rend Blackhand}». Заберіть його голову й поверніться до міста «{zone:Orgrimmar}».",
  ["b57ccd76"] = "Ідіть за НІП «{npc:Reginald Windsor}» через місто «{zone:Stormwind}». Захистіть його від небезпеки!",
  ["b58a5bc5"] = "Зачекайте, поки «{npc:Thun'grim Firegaze}» закінчить вашу броню.",
  ["b5a18a15"] = "Здобудьте предмет «{item:Obsidian Power Source}» і принесіть його до НІП «{npc:Tabetha}» у локації «{zone:Dustwallow Marsh}».",
  ["b5d6e143"] = "Принесіть «{item:Wavethrasher Scales}»: 6 шт. до НІП «{npc:Ogtinc}» у локації «{zone:Azshara}». НІП «{npc:Ogtinc}» живе на вершині скель на північний схід від місцевості «{zone:Ruins of Eldarath}».",
  ["b5f5b4bf"] = "Віддайте НІП «{npc:Aurius}» предмет «{item:Medallion of Faith}» до бою з бароном; поговоріть із ним, коли бос «{npc:Baron Rivendare}» загине.",
  ["b611df01"] = "Убийте ворога «{npc:Ambassador Infernus}» у фортеці «{zone:Angor Fortress}» і принесіть доказ його смерті до НІП «{npc:Advisor Belgrum}» у місті «{zone:Ironforge}».",
  ["b6854794"] = "Поговоріть з НІП «{npc:Thrall}», якщо готові взятися за задуману ним місію.",
  ["b68cb47f"] = "Вислухайте, як НІП «{npc:Royal Historian Archesonus}» переказує історію Тауріссана.",
  ["b6e50d32"] = "Поговоріть із НІП «{npc:Shadowmage Vivian Lagrave}».",
  ["b73c9c4e"] = "Пошукайте огра з місцевості «{zone:Bolder'ok}» у найближчій печері.",
  ["b7af21dd"] = "Поговоріть з НІП «{npc:Franclorn Forgewright}», якщо хочете отримати ключ від міста.",
  ["b7d4102d"] = "Віднесіть мініатюрну копію «{zone:The Discs of Norgannon}» одному з мудреців у місті «{zone:Thunder Bluff}».",
  ["b8078b8a"] = "За допомогою отриманої записки знайдіть схований скарб.",
  ["b8158b0b"] = "Убийте дворфів Темного Заліза: 10, «{npc:Dark Iron Tunneler}»: 5, «{npc:Dark Iron Saboteur}»: 5 і «{npc:Dark Iron Demolitionist}»: 5 у місцевості «{zone:Dun Modr}».",
  ["b81c3d1c"] = "Здобудьте предмет «{item:Gordok Shackle Key}» з огрів північного крила і звільніть Нота; у його схованці є здобич.",
  ["b83e58ec"] = "Установіть предмет «{item:Timbermaw War Banner}» у місцевості «{zone:Legashi Stronghold}» у локації «{zone:Azshara}». Убийте боса і повідомте про перемогу НІП «{npc:Gatekeeper Rageroar}» у місцевості «{zone:Ursolan}».",
  ["b89179a2"] = "Принесіть двадцять чотири предмети «{item:Robo-mechanical Guts}» до НІП, що дав завдання, у місті «{zone:Stormwind}».",
  ["b8a122c5"] = "Віднесіть предмет «{item:Brilliant Gold Ring}» до НІП «{npc:Nogg}» у місті «{zone:Orgrimmar}».",
  ["b9864f2b"] = "Ідіть за обгорілою запискою з локації «{zone:Westfall}» до місця-двійника: обгорілих решток біля згорілої вежі на південь від «{zone:Camp Taurajo}» у локації «{zone:The Barrens}».",
  ["b986b68d"] = "Потрібне перед завданням «{quest:Red Silk Bandanas}».",
  ["b98f8f61"] = "Супроводьте НІП «{npc:Kernobee}» до виходу з місцевості «{zone:The Clockwerk Run}», потім зверніться до НІП «{npc:Scooty}» у місцевості «{zone:Booty Bay}».",
  ["b9b27ca2"] = "Потрібні завдання одного й того самого НІП у місті «{zone:Dalaran}». Два додаткові завдання від НІП «{npc:Keeper Bel'varil}» необов’язкові й для допуску не потрібні.",
  ["b9c31cdd"] = "Здолайте «{npc:Twilight Raider}»: 8, «{npc:Twilight Shadowmancer}»: 8 і «{npc:Twilight Neophyte}»: 8 у місцевості «{zone:Sunnyglade}» для НІП «{npc:Tran'gul}» у місцевості «{zone:Rog'mar}».",
  ["b9e41f80"] = "Вирушайте до місцевості «{zone:The Sepulcher}» у локації «{zone:Silverpine Forest}» і поговоріть з НІП «{npc:Trevan Rol}» про зниклих мандрівників Земляного Кільця.",
  ["ba3d70aa"] = "Потрібне перед завданням «{quest:Heartwoven}».",
  ["ba7be09d"] = "Пошукайте в підземеллі «{zone:Dire Maul}» зниклого НІП. Повідомте все, що дізнаєтеся, НІП «{npc:Sage Korolusk}» у місцевості «{zone:Camp Mojache}».",
  ["ba87c074"] = "Вирушайте до підземелля «{zone:Blackrock Depths}» і знищте мерзенних загарбників! НІП «{npc:Warlord Goretooth}» хоче, щоб ви вбили «{npc:Anvilrage Medic}»: 10, «{npc:Anvilrage Soldier}»: 10 і «{npc:Anvilrage Officer}»: 10. Виконавши завдання, поверніться до нього.",
  ["bab6b202"] = "Вирушайте до підземелля «{zone:Maraudon}» і здобудьте предмет «{item:Vial of Earth Song Water}», потім загасіть ним полум’я НІП «{npc:Woodwyrd}» у місцевості «{zone:Forlorn Gardens}».",
  ["baf04e98"] = "Друге завдання цього ланцюжка.",
  ["bb38ae3d"] = "Розшукайте НІП «{npc:Argent Guard Thaelrid}» у підземеллі «{zone:Blackfathom Deeps}».",
  ["bbbe64e8"] = "Принесіть еліксири «{item:Elixir of Shadow Power}»: 10 шт. до НІП «{npc:Gorzeeki Wildeyes}» у локації «{zone:Burning Steppes}».",
  ["bc2a5208"] = "Здобудьте «{item:Healthy Courser Gland}»: 4 шт. і принесіть їх до НІП «{npc:Ogtinc}» у локації «{zone:Azshara}». НІП «{npc:Ogtinc}» живе на вершині скель на північний схід від місцевості «{zone:Ruins of Eldarath}».",
  ["bc881c61"] = "Вступний крок до завдання «{quest:Tiara of the Deep}».",
  ["bcc41ed9"] = "Предмет «{item:Celebrian Rod}» випадає з боса «{npc:Noxxion}», а «{item:Celebrian Diamond}» — з боса «{npc:Lord Vyletongue}».",
  ["bceda7f4"] = "Заберіть родинний скарб НІП «{npc:Patrick Garrett}» з родинної скрині в залі «{zone:South Common Hall}» підземелля «{zone:Uldaman}» і принесіть йому в місто «{zone:Undercity}».",
  ["bd237bf2"] = "НІП «{npc:Fel'zerul}» у місцевості «{zone:Stonard}» просить вас зібрати «{item:Atal'ai Artifact}»: 10 шт.",
  ["bd632d8f"] = "Потім цей НІП видає ще три завдання.",
  ["bd7b7b2d"] = "Здолайте боса «{npc:Overlord Kilgar}» у місцевості «{zone:Twilight's Shroud}» і принесіть його голову до НІП «{npc:Sergeant Riftan}».",
  ["bdcc9025"] = "Медальйон випадає з боса «{npc:Nekrum Gutchewer}».",
  ["bddbf95e"] = "Убийте боса «{npc:Lord Incendius}» біля ковадла в Глибинах Блекрок і принесіть предмет «{item:Tablet of Kurniya}».",
  ["be29b758"] = "Потрібне, щоб стало доступним завдання «{quest:Smart Drinks}».",
  ["be8f86fd"] = "Три з п’яти самоцвітів — у ханів ПОЗА підземеллям, у зовнішніх печерах.",
  ["bf3d943b"] = "Вирушайте до підземелля «{zone:Stratholme}» і знайдіть НІП «{npc:Archivist Galford}». Знищте його і спаліть архів.",
  ["bf53139e"] = "Класове завдання шамана. Потрібен предмет «{item:Voodoo Feathers}»: 2 бурштинові, 2 сині й 2 зелені пера від шести тролів-охоронців: НІП «{npc:Gasher}», «{npc:Mijan}», «{npc:Zolo}», «{npc:Hukku}», «{npc:Zul'Lor}» і «{npc:Loro}».",
  ["bf754726"] = "Вирушайте до підземелля «{zone:Blackrock Spire}», убийте боса «{npc:Goraluk Anvilcrack}» і застосуйте до його трупа предмет «{item:Blood Stained Pike}». Також знайдіть предмет «{item:Unforged Rune Covered Breastplate}». Віднесіть предмет «{item:Soul Stained Pike}» і нагрудник до НІП «{npc:Lorax}» у локації «{zone:Winterspring}».",
  ["bfa438b6"] = "Доставте предмет «{item:Abominable Head}» до міста «{zone:Undercity}».",
  ["bfce1490"] = "НІП «{npc:Andrew Brownell}» просить вас убити боса «{npc:Amnennar the Coldbringer}» і принести його череп.",
  ["bfef45bd"] = "Принесіть предмет «{item:Ribbly's Head}» до НІП «{npc:Yuka Screwspigot}» у локації «{zone:Burning Steppes}».",
  ["c045f5f4"] = "Увійдіть до печер «{zone:Rethban Caverns}», дійдіть до першої розвилки й вчасно поверніться до НІП «{npc:Yorus Barleybrew}». Не можна загинути й відпустити дух.",
  ["c058e22b"] = "Вступний крок до завдання «{quest:Forging the Mightstone}».",
  ["c0ec53ca"] = "Поговоріть з НІП «{npc:Kharan Mighthammer}» і дізнайтеся про викрадення НІП «{npc:Princess Moira Bronzebeard}». Передайте ці відомості НІП «{npc:Thrall}» у місті «{zone:Orgrimmar}». Ви пам’ятаєте, як командир Ґор’шак казав, що Карана тримають у камері неподалік.",
  ["c11c3a7d"] = "Ваш наставник воїнів («{npc:Wu Shen}» у місті «{zone:Stormwind}» або наставники в містах «{zone:Ironforge}» і «{zone:Darnassus}») спершу відправляє вас до НІП «{npc:Yorus Barleybrew}» у місцевості «{zone:Lakeshire}». Проходження обмежене в часі.",
  ["c139c87e"] = "Спершу поговоріть із Кам’яним вартовим і активуйте диски. Потім віддайте талон на нагороду НІП «{npc:Bena Winterhoof}» у місті «{zone:Thunder Bluff}» і виберіть нагороду.",
  ["c15ef2e1"] = "Принесіть «{item:Crude Flint}»: 9 шт. НІП «{npc:Rethiel the Greenwarden}».",
  ["c1c46763"] = "Зверніться до НІП «{npc:Image of Archmage Modera}» біля підземелля «{zone:City of Dalaran}».",
  ["c211c240"] = "Жезл випадає з боса «{npc:Sergeant Bly}» після події на піраміді.",
  ["c246e9c5"] = "НІП «{npc:Ambassador Malcin}» — у наметах зовнішнього тернового лабіринту, перед порталом підземелля. Починається з предмета «{item:Small Scroll}», що випадає з боса «{npc:Charlga Razorflank}» у підземеллі «{zone:Razorfen Kraul}».",
  ["c28d4980"] = "Віднесіть предмет «{item:Elemental Shard Sample}» до НІП «{npc:Lotwil Veriatus}». Ви пам’ятаєте, що, за словами Теодори, Лотвіл стоїть табором на сході.",
  ["c31190bb"] = "Здобудьте кристал «{item:An'she's Radiance}» у підземеллі «{zone:Maraudon}» і віднесіть його до НІП «{npc:Olana Brighthoof}» у локації «{zone:Mulgore}».",
  ["c3454a11"] = "Зберіть предмет «{item:Arcane Mote}» для НІП «{npc:Image of Archmage Modera}» біля підземелля «{zone:City of Dalaran}».",
  ["c41dcb40"] = "Передайте НІП «{npc:Thrall}» у місті «{zone:Orgrimmar}» звістку про долю НІП «{npc:Varian Wrynn}».",
  ["c494adde"] = "Заберіть предмет «{item:Stone Circle}» з майстерні НІП «{npc:Marvon Rivetseeker}» у місцевості «{zone:Ratchet}».",
  ["c4969b8c"] = "Принесіть стихії землі, повітря, вогню і води НІП «{npc:Bath'rah the Windwatcher}».",
  ["c685ce08"] = "Заберіть предмет «{item:Putrid Vine}» у вартового на дні підземелля «{zone:Sunken Temple}» і поверніться до НІП «{npc:Torwa Pathfinder}».",
  ["c6ac55db"] = "Гірнича справа 230. Поговоріть з НІП «{npc:Gloom'rel}» перед боєм із босами; покладіть у «{zone:Spectral Chalice}» «{item:Star Ruby}»: 2 шт., «{item:Gold Bar}»: 20 шт. і «{item:Truesilver Bar}»: 10 шт., щоб вивчити рецепт плавлення.",
  ["c6b43cd5"] = "Здобудьте предмет «{item:Tome of Twilight}» у підземеллі «{zone:Krol'dok Stronghold}».",
  ["c756c365"] = "Під час ритуалу нападають хвилі нежиті. Потім поговоріть із жаровнею біля ідола, щоб завершити.",
  ["c7ef6468"] = "Принесіть до НІП «{npc:Thrall}» предмет «{item:Lieutenant's Insignia}», здобутий у культистів Палаючого Клинка в місцевості «{zone:Skull Rock}».",
  ["c8e15522"] = "Поговоріть з НІП «{npc:Gryphon Master Talonaxe}» усередині тамтешнього пташника грифонів.",
  ["c9060e87"] = "Вирушайте до підземелля «{zone:Stratholme}» і знищте боса «{npc:Baron Rivendare}». Заберіть його голову і поверніться до НІП «{npc:Duke Nicholas Zverenhoff}».",
  ["c9670fd8"] = "Зберіть 14 предметів «{item:Summoner's Salt}» з орків у локації «{zone:Redridge Mountains}» і поверніться до НІП «{npc:Ursula Deline}».",
  ["c9c17b5f"] = "Здобудьте обидві частини предмета «{item:Scepter of Celebras}»: «{item:Celebrian Rod}» і «{item:Celebrian Diamond}». Знайдіть спосіб поговорити з НІП, пов’язаним зі скіпетром.",
  ["c9cc9ece"] = "Принесіть предмет «{item:Tablet of Ryun'eh}» до НІП «{npc:Theldurin the Lost}».",
  ["ca0ebee2"] = "Увійдіть у підземелля «{zone:Blackmaw Hold}» і здобудьте «{item:Blackmaw Pouch}»: 5 шт. для НІП біля «{zone:Ruins of Eldarath}» у локації «{zone:Azshara}».",
  ["ca18742e"] = "Принесіть голову боса й предмет «{item:Roughshod Pike}» до купи підношень за павуками, щоб почалися хвилі ворогів.",
  ["ca3b7b07"] = "Виконується разом із завданням «{quest:Carving a Path}».",
  ["cac9d89f"] = "Його видає також НІП «{npc:Xanis Flameweaver}» у місті «{zone:Thunder Bluff}», а шаманам-небородженим — ще й НІП «{npc:Alaana Stormwalker}» у локації «{zone:Mulgore}» (33.4, 22.4): зараховується будь-яке з цих завдань. НІП «{npc:Prate Cloudseer}» дає вам предмет «{item:Air Totem}» і наступне завдання.",
  ["cad6ab93"] = "Викрадіть 6 предметів «{item:Feed Satchel}» з ферми Альянсу у місцевості «{zone:Meadowsbrook}», а потім поверніться до НІП «{npc:Krom'rosh}».",
  ["caea8a17"] = "Перш ніж почати це завдання, переконайтеся, що кожен гравець у вашій групі виконав попередній крок.",
  ["caf8e4e5"] = "Принесіть предмет «{item:Doomrigger's Clasp}» до НІП «{npc:Mayara Brightwing}» у локації «{zone:Burning Steppes}».",
  ["cb01dba1"] = "Знайдіть у місцевості «{zone:Rog'mar}» когось, хто може знати про ливарну форму.",
  ["cb09db08"] = "Віднесіть предмет «{item:Reed-woven Heart}» назад до НІП «{npc:Caitlin Grassman}» у місцевості «{zone:Menethil Harbor}».",
  ["cb1eaf6c"] = "Поговоріть із НІП «{npc:Talo Thornhoof}» у місцевості «{zone:Camp Mojache}» у локації «{zone:Feralas}».",
  ["cb34492d"] = "Не дайте принцесі Мойрі загинути й поговоріть із нею після смерті імператора Даґрана Тауріссана. Її завдання відправить вас по нагороду назад до НІП «{npc:Thrall}».",
  ["cb8b2d44"] = "Вирушайте до локації «{zone:Winterspring}» і знайдіть НІП «{npc:Haleh}». Віддайте їй луску дракона «{npc:Awbee}».",
  ["cb8e1514"] = "Єдині такі пристрої поза підземеллям: на піднятій платформі в місцевості «{zone:Train Depot}» і біля входу в місцевість «{zone:The Workshop}» (задній вхід).",
  ["cbb4cccf"] = "Знайдіть НІП «{npc:Egan}». Ви знаєте лише, що востаннє його бачили біля підземелля «{zone:Stratholme}».",
  ["cbd15fef"] = "Знайдіть НІП «{npc:Deathstalker Adamant}» і «{npc:Deathstalker Vincent}» у підземеллі «{zone:Shadowfang Keep}».",
  ["cc1b9019"] = "НІП «{npc:Chieftain Bloodmaw}» перебуває в локації «{zone:Felwood}», на південь від місцевості «{zone:Timbermaw Hold}».",
  ["cc77c527"] = "Вирушайте до місцевості «{zone:The Undercroft}» у найпівденнішій частині локації «{zone:Eastern Plaguelands}» і здобудьте предмет «{item:Taelan's Hammer}». Виконавши це, поверніться до НІП «{npc:Tirion Fordring}».",
  ["ccb1c447"] = "Вирушайте до району «{zone:Dwarven District}» у місті «{zone:Stormwind}» і знайдіть інженера, який допоможе з вибухівкою.",
  ["cd0a9cf3"] = "Частина ланцюжка Орди до Оніксії. Ці очі випадають із драконідів у Верхньому Шпилі Блекрок.",
  ["cd312431"] = "Знайдіть безбарвний предмет «{item:Drained Crystal Fragment}» біля кристала у підземеллі «{zone:Shaper's Terrace}».",
  ["cdf00b8b"] = "Принесіть предмет «{item:Bundle of Atal'ai Artifacts}» до НІП «{npc:Atal'ai Exile}» у локації «{zone:The Hinterlands}».",
  ["cdf10411"] = "Поговоріть з НІП «{npc:Ragged John}», щоб дізнатися про долю НІП «{npc:Marshal Windsor}», а потім поверніться до НІП «{npc:Marshal Maxwell}». Ви пам’ятаєте, як НІП «{npc:Marshal Maxwell}» радив шукати його в печері на півночі.",
  ["ce665b14"] = "«{npc:Qiaga the Keeper}» і «{npc:Morta'gya the Keeper}» — елітні вороги 50 рівня, а навколо них заклиначі; шлях до верхнього вівтаря повний тролів 45-50 рівня: візьміть групу або підкрадіться. Кожен у групі може забрати предмет «{item:Sacred Mallet}», і його можна використати в бою. Одного предмета «{item:Mallet of Zul'Farrak}» на групу досить, і він викликає боса «{npc:Gahz'rilla}» в усіх наступних проходженнях.",
  ["ce72ca7f"] = "Нове в цій версії гри: це завдання йде перед завданням «{quest:Warlord's Command}».",
  ["ce973e47"] = "Класове завдання шамана з 30-го рівня; відкривається попереднім завданням шамана (завдання з предметом «{item:Air Totem}»). У цьому підземеллі: «{quest:Elemental Aid}». Убийте боса «{npc:Charlga Razorflank}» і заберіть предмет «{item:Tattered Note}»; його отримує кожен шаман із цим завданням. Далі: 20 викривлених тотемів із чотирьох локацій і елітний ритуал у локації «{zone:Thousand Needles}».",
  ["ce9cd066"] = "Здобудьте осколки й уламки пілонів, що їх охороняють у селищах Маґрамів і Ґелкісів. Поверніть їх до НІП «{npc:Mordent Evenshade}».",
  ["cef2df52"] = "Захистіть НІП «{npc:Daphne Stilwell}» від нападу Дефіасів.",
  ["cf5059d1"] = "Попередження: якщо не виконати це завдання до прийняття завдання «%s», воно стане недоступним.",
  ["cf7d7aac"] = "Поговоріть із НІП «{npc:Malyfous Darkhammer}» у місцевості «{zone:Everlook}».",
  ["cff4b6fb"] = "Вирушайте до місцевості «{zone:Wyrmbog}» у локації «{zone:Dustwallow Marsh}». Знайдіть стародавнього дрейка «{npc:Emberstrife}» і бийте його, доки не зламаєте його волю. Покладіть перед ним предмет «{item:Unforged Seal of Ascension}», потім застосуйте до нього предмет «{item:Orb of Draconic Energy}» і змусьте його спрямувати своє полум’я на предмет «{item:Unforged Seal of Ascension}».",
  ["d04cdd68"] = "Віднесіть предмет «{item:Brilliant Gold Ring}» до НІП «{npc:Talvash del Kissel}» у місті «{zone:Ironforge}».",
  ["d05f32f8"] = "Зберіть предмет «{item:Arcane Mote}» у підземеллі «{zone:City of Dalaran}» для НІП «{npc:Magus Wordeen Voidglare}» у місцевості «{zone:Tarren Mill}».",
  ["d0824774"] = "Вирушайте до локації «{zone:Wetlands}» і зустріньтеся з НІП «{npc:Deathstalker Agent}» на пагорбах над табором Драконячої Пащі.",
  ["d0b5b948"] = "Увійдіть до підземелля «{zone:Alcaz Prison}» і дізнайтеся, що сталося з НІП «{npc:King of Stormwind}».",
  ["d0ce6884"] = "Поговоріть з НІП «{npc:Nathanos Blightcaller}» у локації «{zone:Eastern Plaguelands}». Кажуть, він оселився в місцевості «{zone:The Marris Stead}».",
  ["d11a6ef6"] = "Зберіть «{item:Stratholme Holy Water}»: 5 шт. з ящиків із припасами на вулицях; з деяких ящиків вилазять вороги.",
  ["d182ea34"] = "Крок Орди, потрібний перед завданням «{quest:Nogg's Ring Redo}».",
  ["d1bfeb3c"] = "Зберіть «{item:Twilight Page}»: 5 шт. у місцевості «{zone:Sunnyglade}» для НІП «{npc:Ashe Amberhall}» у фортеці «{zone:Farholde Keep}».",
  ["d1c53ab1"] = "Книга класу «Паладин». Клацніть на книгу, щоб почати завдання.",
  ["d1cc1951"] = "Знайдіть предмет «{item:Symbol of Ragnaros}» і принесіть його НІП «{npc:Velarok Windblade}».",
  ["d207c433"] = "Виконується разом з іншим завданням.",
  ["d207f0ba"] = "Принесіть предмет «{item:Satchel of Cursed Mementos}» до НІП «{npc:Ashe Amberhall}» у фортеці «{zone:Farholde Keep}».",
  ["d208a8fc"] = "Крок у підземеллі «{zone:Razorfen Kraul}». НІП «{npc:Prate Cloudseer}» видає його, коли ви здаєте завдання «{quest:Call of Air}»; здайте його НІП «{npc:Rau Cliffrunner}» у місцевості «{zone:Freewind Post}». На боці Орди цим завданням не можна поділитися.",
  ["d224d2a2"] = "Убийте боса «{npc:Targorr the Dread}» у підземеллі «{zone:The Stockade}» і віднесіть його голову до НІП «{npc:Guard Berton}».",
  ["d23653fc"] = "У місцевості «{zone:Emerald Sanctuary}» спершу взаємодійте з конем (51.0, 81.8), а тоді йдіть за його слідом у локації «{zone:Felwood}» до нього (45.0, 52.0). Потім поговоріть з ним і з НІП: той видає завдання про особливі матеріали.",
  ["d28bdecb"] = "Останній крок. Нагорода — предмет «{item:Brutal Hauberk}».",
  ["d2aa22a6"] = "Знайдіть тіло НІП «{npc:Maur Grimtotem}» у підземеллі «{zone:Ragefire Chasm}» і перевірте, чи немає при ньому чогось цікавого.",
  ["d303a745"] = "Це ланцюжок завдань із кроком у підземеллі «{zone:Razorfen Kraul}»",
  ["d3087b8a"] = "Убийте 5 НІП «{npc:Legashi Satyr}», 5 НІП «{npc:Legashi Rogue}» і 5 НІП «{npc:Legashi Hellcaller}» для замовника біля місцевості «{zone:Ruins of Eldarath}».",
  ["d3339aef"] = "Книга класу «Жрець». Клацніть на книгу, щоб почати завдання.",
  ["d3617ed7"] = "Принесіть яйця «{item:Collected Dragon Egg}»: 8 шт. і предмет «{item:Collectronic Module}» до НІП «{npc:Tinkee Steamboil}» у місцевості «{zone:Flame Crest}» у локації «{zone:Burning Steppes}».",
  ["d3d49a06"] = "Поговоріть з НІП «{npc:Trevan Rol}» у місцевості «{zone:The Sepulcher}» і принесіть йому потрібні матеріали.",
  ["d41ca256"] = "Класове завдання паладина для людей і дворфів. У цьому підземеллі предмет «{item:Corrupted Kor Gem}» випадає з блекфатомських морських відьом усередині, а також із блекфатомських жриць припливу та оракулів біля входу в локації «{zone:Ashenvale}». НІП «{npc:Thundris Windweaver}» у місцевості «{zone:Auberdine}» очищає його. Інші частини: «{item:Whitestone Oak Lumber}» («{zone:The Deadmines}»), «{item:Jordan's Smithing Hammer}» («{zone:Shadowfang Keep}») і партія руди НІП «Джордан» («{zone:Loch Modan}»).",
  ["d432088b"] = "Знайдіть командира всередині підземелля «{zone:Alcaz Prison}».",
  ["d45f5e54"] = "Використайте предмет «{item:Filled Cerulean Vial}» на цих рослинах (ліанах). Їх не можна клацнути чи взяти в ціль, тож виглядайте їх у помаранчевому крилі.",
  ["d4819af9"] = "Віднесіть предмет «{item:Head of Balnazzar}» до НІП «{npc:Duke Nicholas Zverenhoff}» у локації «{zone:Eastern Plaguelands}».",
  ["d4abf2b6"] = "З будь-якої нежиті в підземеллі «{zone:Stratholme}» можуть випасти предмети для цього завдання.",
  ["d4ce47b5"] = "Класове завдання розбійника. Предмет «{item:Azure Key}» випадає з боса «{npc:Morphaz}».\n\nНеобов’язкове вступне завдання:",
  ["d53c28ba"] = "Поверніть предмет «{item:Crest of Lordaeron}» до міста «{zone:Stormwind}».",
  ["d57852e2"] = "Доставте предмет «{item:Treaty of Understanding}» до НІП «Маґні Бронзбірд» у місті «{zone:Ironforge}».",
  ["d5d4248b"] = "Вирушайте до підземелля «{zone:Stratholme}» і обшукайте зикурати. Знайдіть свіжий предмет «{item:Scourge Data}» і принесіть його до НІП «{npc:Betina Bigglezink}».",
  ["d67ed842"] = "Убийте шістьох тролів-охоронців на балконах, щоб зняти бар’єр Джаммал’ана, а потім принесіть його голову.",
  ["d746161e"] = "Зберіть «{item:Intact Raptor Horn}»: 5 шт. із рапторів-косопазурів Сонцелусків і принесіть їх до НІП «{npc:Mebok Mizzyrix}».",
  ["d7748c90"] = "Принесіть «{item:Deviate Hide}»: 20 шт. НІП «{npc:Nalpak}».",
  ["d7da7c7c"] = "Знайдіть у фортеці «{zone:Farholde Keep}» когось, хто може знати про ливарну форму.",
  ["d7ec74a1"] = "Потім НІП «{npc:Lord Maxwell Tyrosus}» і «{zone:The Argent Hold}» у місцевості «{zone:Light's Hope Chapel}» дають нагороду: зброю або щит.",
  ["d80b149d"] = "Відкрийте скриню.",
  ["d83bee16"] = "Частина 2 ланцюжка завдань Антіона Гармона: попередні завдання відкривають цей крок.",
  ["d8fc7554"] = "Можна вбити НІП «{npc:Qiaga the Keeper}» на верхівці вівтаря, щоб здобути предмет «{item:Sacred Mallet}».",
  ["d973cc01"] = "Групове завдання: корчма стоїть у місцевості «{zone:Pyrewood Village}», серед ворожих селян.",
  ["d9858ce0"] = "Убийте «{npc:Plaguehound Runt}»: 20, «{npc:Plaguehound}»: 5 і «{npc:Frenzied Plaguehound}»: 5. Коли впораєтеся, поверніться до НІП «{npc:Tirion Fordring}».",
  ["d9ba00a6"] = "Перший обов’язковий крок завдання «{quest:Hidden Enemies}» для ланцюжка підземелля «{zone:Ragefire Chasm}».",
  ["d9bccd0a"] = "Дослідіть місцевість «{zone:Fenris Isle}» на сході й дізнайтеся про долю загону мандрівників Земляного Кільця.",
  ["da15ba29"] = "Проникніть у підземелля «{zone:Krol'dok Stronghold}» і поверніться до НІП «{npc:Krom'rosh}» із доказом загибелі їхнього ватажка.",
  ["da17b288"] = "Крок Альянсу, потрібний перед завданням «{quest:Gnome Improvement}».",
  ["da4a635d"] = "Вступний крок до завдання «{quest:Researching the Corruption}».",
  ["da4d7c62"] = "Убийте НІП «{npc:Chieftain Bloodmaw}» і принесіть його булаву НІП «{npc:Gorn One Eye}» у місцевості «{zone:Timbermaw Hold}».",
  ["da96696a"] = "Віднесіть предмет «{item:Bolvar's Decree}» до НІП «{npc:Magistrate Solomon}» у місцевості «{zone:Lakeshire}».",
  ["dad9783e"] = "Вирушайте до підземелля «{zone:Blackrock Spire}» і знищте босів «{npc:War Master Voone}», «{npc:Highlord Omokk}» та «{npc:Overlord Wyrmthalak}». Коли впораєтеся, поверніться до НІП «{npc:Marshal Maxwell}».",
  ["db03e9fd"] = "Принесіть «{item:Thorium Plated Dagger}»: 8 НІП «{npc:Velarok Windblade}».",
  ["db3101d0"] = "Поговоріть з НІП «{npc:Prospector Ironband}» на розкопках «{zone:Ironband's Excavation Site}» у локації «{zone:Loch Modan}».",
  ["db34934c"] = "Убийте «{npc:Noxious Plaguebat}»: 20 і «{npc:Monstrous Plaguebat}»: 10. Коли закінчите, поверніться до НІП «{npc:Nathanos Blightcaller}».",
  ["dc019211"] = "Віддайте НІП «{npc:Aurius}» предмет «{item:Medallion of Faith}»; він приєднається до бою з босом «{npc:Baron Rivendare}». Після бою заберіть у нього нагороду.",
  ["dc39ba7e"] = "Віднесіть предмет «{item:Shaw's Report}» до НІП «{npc:Gryan Stoutmantle}» у локації «{zone:Westfall}».",
  ["dc6f686e"] = "Розшукайте НІП «{npc:Rexxar}». Вождь розповів вам, де його шукати. Обшукайте шляхи локації «{zone:Desolace}» між локаціями «{zone:Stonetalon Mountains}» і «{zone:Feralas}».",
  ["dcdb2e13"] = "Знайдіть затишне місце в горах між «{zone:The Barrens}» і «{zone:Desolace}»: потрібний предмет у покинутому таборі в локації «{zone:Stonetalon Mountains}».",
  ["dd1d6df1"] = "Зачекайте, поки «{npc:Furen Longbeard}» закінчить вашу броню.",
  ["ddb98824"] = "Убийте «{npc:Mana Elemental}» у підземеллі «{zone:City of Dalaran}» і поверніться до НІП «{npc:High Sorcerer Andromath}» у місті «{zone:Stormwind City}».",
  ["ddc03ca3"] = "Класове завдання чорнокнижника. Уламки випадають у підземеллях «{zone:Shadowfang Keep}» і «{zone:Blackfathom Deeps}».",
  ["dde0b66d"] = "Наповніть предмет «{item:Egg of Hakkar}» з хаккарійських хоронителів крові, щоб викликати НІП «{npc:Avatar of Hakkar}».",
  ["ddfca6d0"] = "Вирушайте до місцевості «{zone:Blackrock Mountain}» на північному заході й увійдіть до підземелля «{zone:Blackrock Depths}». З’ясуйте, що сталося з НІП «{npc:Marshal Windsor}». Ви пам’ятаєте, як НІП «{npc:Ragged John}» розповідав, що Віндзора потягли до в’язниці.",
  ["de09c045"] = "Знайдіть Селище Зорепаду в локації «{zone:Winterspring}» і поговоріть із НІП «{npc:Wynd Nightchaser}».",
  ["de37fa9a"] = "Поговоріть з НІП «{npc:Shoni the Shilent}» у місті «{zone:Stormwind}».",
  ["deff02cf"] = "Наступне обов’язкове дослідження оази після завдання «{quest:The Forgotten Pools}».",
  ["df499e60"] = "Після завдання «{quest:Altered Beings}» НІП «Тонга» відправляє вас до НІП «Гамуул».",
  ["df5459f7"] = "Здобудьте предмет «{item:Head of the Baron}» у підземеллі «{zone:Ruins of Lordaeron}».",
  ["df599839"] = "Поверніть предмет «{item:Marshal Windsor's Lost Information}». НІП «{npc:Marshal Windsor}» вважає, що ці відомості зберігаються в босів «{npc:Golem Lord Argelmach}» і «{npc:General Angerforge}».",
  ["df6c8b66"] = "Вирушайте до підземелля «{zone:Blackrock Depths}» і вбийте боса «{npc:Bael'Gar}». Використайте предмет «{item:Altered Black Dragonflight Molt}» на рештках боса «{npc:Bael'Gar}», щоб уловити сутність. Принесіть предмет «{item:Encased Fiery Essence}» до НІП «{npc:Cyrus Therepentous}».",
  ["dfd9ed24"] = "Принесіть предмет «{item:Strange Water Globe}» до НІП «{npc:Je'neu Sancrea}» у місцевості «{zone:Zoram'gar Outpost}» (локація «{zone:Ashenvale}»).",
  ["e039aee3"] = "Другий обов’язковий крок до завдання «{quest:The Stockade Riots}».",
  ["e03edfc6"] = "Супроводьте НІП «{npc:Lumina Windsinger}» і допоможіть їй утекти з місцевості «{zone:Fenris Keep}».",
  ["e0a8478e"] = "Ці вороги поза підземеллям, навколо входу.",
  ["e0d6e812"] = "Нове в цій версії. Книга — у боса «{npc:Arcanist Doan}».",
  ["e1eed8e7"] = "Знайдіть предмет «{item:Gauntlet of Gordok Might}» і поверніть його до НІП «{npc:Captain Kromcrush}» у підземеллі «{zone:Dire Maul}». За словами Кромкраша, «давня байка» каже, що Тортельдрін — «моторошний» ельф, який називав себе принцом, — украв її в одного з королів Ґордоків.",
  ["e256cc28"] = "Заберіть предмет «{item:Medallion of Faith}» у боса «{npc:Malor the Zealous}» у місцевості «{zone:The Scarlet Bastion}» і принесіть його до НІП «{npc:Aurius}».",
  ["e256d845"] = "Елітне завдання: для цього боса візьміть групу.",
  ["e268a948"] = "Принесіть «{zone:Venom Bottle}» аптекареві в місцевості «{zone:Tarren Mill}».",
  ["e2a726b8"] = "Збирається по всьому Монастирю: з будь-якого багряного гуманоїда на шляху до Зброярні може випасти потрібний предмет.",
  ["e2d4cdbd"] = "Знайдіть три самоцвіти командування: «{item:Gemstone of Smolderthorn}», «{item:Gemstone of Spirestone}» і «{item:Gemstone of Bloodaxe}». Принесіть їх разом із предметом «{item:Unadorned Seal of Ascension}» до НІП «{npc:Vaelan}». Генерали: «{npc:War Master Voone}» із клану Тліючого Шипа, «{npc:Highlord Omokk}» із клану Шпилекаменя і «{npc:Overlord Wyrmthalak}» із клану Кривавої Сокири.",
  ["e2eb9cf4"] = "Використайте предмет «{item:Moonsilver Blade}», щоб знищити ціль завдання у локації «{zone:Silverpine Forest}».",
  ["e32e7e5c"] = "Здобудьте 3 предмети «{item:Twilight Missive}» у місцевих ворогів у місцевості «{zone:Sunnyglade}» для НІП «{npc:Tran'gul}» у місцевості «{zone:Rog'mar}».",
  ["e37019c9"] = "Розшукайте й зберіть матеріали для книги заклинань, які просив бібліотекар.",
  ["e3a32ab9"] = "Вирушайте до підземелля «{zone:Stratholme}» і знайдіть «{zone:Menethil's Gift}». Покладіть предмет «{item:Keepsake of Remembrance}» на нечестиву землю.",
  ["e402aece"] = "Вирушайте до підземелля «{zone:Blackrock Depths}» і здобудьте «{item:Dark Iron Fanny Pack}»: 20 шт. Виконавши це, поверніться до НІП «{npc:Oralius}». Ви припускаєте, що ці «поясні сумки» носять дворфи Темного Заліза в підземеллі «{zone:Blackrock Depths}».",
  ["e48fb299"] = "Знайдіть НІП «{npc:Marvon Rivetseeker}» у локації «{zone:Tanaris}».",
  ["e4980264"] = "Предмет «{item:Essence of the Elements}» випадає з елементалів і големів у Глибинах Блекрок.",
  ["e4f17dec"] = "Убийте «{npc:Chogg'Zac}» у печері місцевості «{zone:Sunnyglade}» і зберіть їхні голови для НІП «{npc:Clubtoe}».",
  ["e538e5f8"] = "Заберіть картину, заховану за зображенням двох місяців у кімнаті боса «{npc:Archivist Galford}», перш ніж спалите архіви.",
  ["e54469e4"] = "Принесіть п’ять срібних злитків до НІП «{npc:Talvash del Kissel}» у місті «{zone:Ironforge}».",
  ["e5804cd0"] = "Закладіть вибухівку біля кузні, а потім зустріньтеся з НІП «{npc:Alba Fairmoon}» біля виходу з підземелля «{zone:Deadmines}».",
  ["e5c82e3a"] = "Застосуйте предмет «{item:Soulbound Keepsake}» до боса «{npc:Ras Frostwhisper}», щоб зробити його людиною, потім убийте його і принесіть його людську голову.",
  ["e5d27190"] = "Поговоріть з НІП «{npc:Magus Tirth}» у місцевості «{zone:The Shimmering Flats}».",
  ["e60fdfa4"] = "Убийте боса «{npc:Witch Doctor Zum'rah}» і принесіть предмет «{item:Zum'rah's Head}» до НІП «{npc:Mazu'kon}» у локації «{zone:Mulgore}».",
  ["e634a5f7"] = "Поговоріть зі Стормвіндською розвідкою про те, як здобути віддалений детонатор.",
  ["e64ab5cc"] = "Принесіть предмет «{item:Cask of Scalder}» до НІП «{npc:Furen Longbeard}».",
  ["e6af653a"] = "НІП «{npc:Commander Aggro'gosh}» видає його, щойно здано обидва попередні завдання (одне з них — від НІП «{npc:Kin'weelay}»).",
  ["e6c26f8c"] = "Поговоріть з НІП «{npc:Gatekeeper Rageroar}» у місцевості «{zone:Ursolan}».",
  ["e6e00e7e"] = "Допуск Орди до міста «{zone:Dalaran}». Два додаткові завдання можна виконувати паралельно з ланцюжком, але вони необов’язкові й для допуску не потрібні.",
  ["e71c0a85"] = "Вирушайте на острів «{zone:Caer Darrow}» у південно-центральній частині Чумних Земель і пошукайте будь-які підказки, де може бути картина.",
  ["e73effb2"] = "Кожен учасник рейду має мати в сумках предмет «{item:Drakefire Amulet}», щоб увійти до рейду «{zone:Onyxia's Lair}»; носити його не обов’язково. Останній крок — у підземеллі «Верхній Шпиль Блекрок»: кров боса «{npc:General Drakkisath}».",
  ["e780f0e7"] = "Вдарте дияволозавра предметом «{item:Devilsaur Barb}». Виконавши це, поверніться до НІП «{npc:Torwa Pathfinder}» у локації «{zone:Un'Goro Crater}».",
  ["e7a911d0"] = "Принесіть предмет «{item:Ott's Masterwork}» до НІП «{npc:Trevan Rol}» у локації «{zone:Silverpine Forest}».",
  ["e7d4370c"] = "Принесіть предмет «{item:Atal'ai Tablet Fragment}» до НІП «{npc:Brohann Caskbelly}» у місті «{zone:Stormwind}».",
  ["e7fd037e"] = "Заберіть предмет «{item:Sealed Azure Bag}» у НІП «{npc:Timbermaw Shaman}» у локації «{zone:Azshara}». Потім віднесіть торбу до НІП «{npc:Archmage Xylem}», що теж перебуває в локації «{zone:Azshara}».",
  ["e80cf2f6"] = "Знайдіть зниклого НІП на місці розкопок. Дізнайтеся, що з ним сталося.",
  ["e8aa7b9f"] = "Знайдіть власника предмета «{item:Feathered Charm Necklace}».",
  ["e9105f46"] = "Зберіть «{item:Suspicious Industrial Supplies}»: 8 шт. у місцевості «{zone:Moonbrook}».",
  ["e9878d04"] = "Знайдіть предмет «{item:Horn of Xelthos}» у підземеллі «{zone:Shadowfang Keep}». Потім поверніть його до схованки замовника біля місцевості «{zone:Pyrewood Village}». Замовлення треба виконати самостійно.",
  ["e9dd95e6"] = "Зачекайте, поки «{npc:Scooty}» відкалібрує предмет «{item:Goblin Transponder}».",
  ["e9e9b918"] = "Зберіть «{item:Atal'ai Tablet}»: 10 шт. для НІП «{npc:Brohann Caskbelly}» у місті «{zone:Stormwind}».",
  ["ea058539"] = "Завдання починається з предмета «{item:Blood-Stained Letter}».",
  ["eac31c92"] = "Убийте «{npc:Fen Creeper}»: 12, а потім поверніться до НІП «{npc:Rethiel the Greenwarden}».",
  ["ead3e0d5"] = "НІП «{npc:Brohann Caskbelly}» у місті «{zone:Stormwind}» просить вас знайти підземелля «{zone:Temple of Atal'Hakkar}».",
  ["eaea96a3"] = "Вступний крок до завдання «{quest:In the Name of the Light}».",
  ["eb3eaaa6"] = "Поговоріть з НІП «{npc:Katherine the Pure}» у місцевості «{zone:Cathedral of Light}» у місті «{zone:Stormwind}».",
  ["eb7213a7"] = "Спустіться ліфтом; термінал — у першому проході праворуч.",
  ["eb9e5060"] = "Знайдіть НІП «{npc:Lord Incendius}» у підземеллі «{zone:Blackrock Depths}» і знищте його!",
  ["ec3c455c"] = "Дослідіть місцевість «{zone:Forlorn Gardens}» біля місцевості «{zone:Shen'dralas}», а потім поверніться до НІП «{npc:Mithera}» у храм неподалік.",
  ["ec6be8bb"] = "Розшукайте в цьому краї трупних личинок і пожирачів. Убийте їх і заберіть їхнє м’ясо. Коли зберете «{item:Slab of Carrion Worm Meat}»: 15 шт., поверніться до НІП «{npc:Tirion Fordring}».",
  ["ece710ad"] = "Поговоріть з НІП «{npc:Squire Maltrake}».",
  ["ece77cad"] = "Знайдіть НІП «{npc:Daphne Stilwell}» у локації «{zone:Westfall}».",
  ["ecfe9a86"] = "Використайте предмет «{item:Divination Scryer}» у самому серці підвалу місцевості «{zone:The Great Ossuary}» в підземеллі «{zone:Scholomance}». Так ви викличете духів, яких маєте судити. Перемога над ними викличе боса «{npc:Death Knight Darkreaver}». Здолайте його і поверніть утрачену душу полеглого бойового коня. Віддайте предмети «{item:Charger's Redeemed Soul}» і другий предмет із завдання НІП «{npc:Darkreaver's Fallen Charger}».",
  ["ed1c082a"] = "Віднесіть предмет «{item:General Drakkisath's Command}» до НІП «{npc:Marshal Maxwell}» у локації «{zone:Burning Steppes}».",
  ["ed33cabf"] = "Зберіть «{item:Cultist Ear}»: 15 шт. з членів культу «{npc:Twilight's Hammer}» у підземеллі «{zone:Krol'dok Stronghold}».",
  ["ed541f92"] = "Убийте НІП «{npc:Qiaga the Keeper}», щоб забрати предмет «{item:Sacred Mallet}».",
  ["edcae722"] = "Віднесіть мініатюрну копію «{zone:The Discs of Norgannon}» до організації «{npc:Explorers' League}» у місті «{zone:Ironforge}».",
  ["edd240ee"] = "Убийте босів «{npc:Highlord Omokk}», «{npc:War Master Voone}» та «{npc:Overlord Wyrmthalak}». Здобудьте предмет «{item:Important Blackrock Documents}». Виконавши завдання, поверніться до НІП «{npc:Warlord Goretooth}» у місцевості «{zone:Kargath}».",
  ["ee584c42"] = "Маєте завдання «{quest:Tran'rek}» у журналі завдань? Спершу здайте його НІП «{npc:Tran'rek}»: доти ви не зможете взяти завдання «{quest:Scarab Shells}», навіть якщо хтось ним поділиться.",
  ["ee825a72"] = "Заодно візьміть предмет «{item:Key to the City}» у НІП «{npc:Magus Wordeen Voidglare}».",
  ["ee997802"] = "Розвідайте територію трохи на захід від місцевості «{zone:The Vile Reef}», знайдіть вхід до печери, потім поверніться з доповіддю до НІП «{npc:Kin'weelay}».",
  ["ef036db7"] = "Убийте боса «Рат’маель» у підземеллі «{zone:Ruins of Lordaeron}».",
  ["ef0a94a5"] = "Вирушайте до підземелля «{zone:Stratholme}» і врятуйте НІП «{npc:Ysida Harmon}» від боса «{npc:Baron Rivendare}».",
  ["efb47b1a"] = "Поговоріть з НІП «{npc:Jordan Stilwell}» у місті «{zone:Ironforge}».",
  ["efb74d18"] = "Поверніться до того ж НІП у місцевості «{zone:Stonard}».",
  ["efd023fa"] = "Знайдіть НІП «{npc:Commander Gor'shak}» у підземеллі «{zone:Blackrock Depths}». Ви пам’ятаєте, що на грубо намальованому портреті орка були ґрати. Можливо, варто пошукати якусь в’язницю.",
  ["f05ba63d"] = "Знайдіть боса «{npc:Doctor Theolen Krastinov}» у підземеллі «{zone:Scholomance}». Знищте його, а тоді спаліть останки НІП «{npc:Eva Sarkhoff}» і «{npc:Lucien Sarkhoff}». Виконавши це, поверніться до НІП «{npc:Eva Sarkhoff}».",
  ["f0622cae"] = "Віднесіть цей переклад до НІП «{npc:Historian Karnik}» у місті «{zone:Ironforge}».",
  ["f0e72313"] = "Останній обов’язковий крок перед завданням «{quest:Horrors in the Highland}».",
  ["f123e54d"] = "Пошукайте сліди того, кого ви розшукуєте, у місцевості «{zone:Emerald Sanctuary}» в локації «{zone:Felwood}».",
  ["f13d4d22"] = "Класове завдання паладина для нежиті й тауренів. У цьому підземеллі предмет «{item:Whitestone Oak Lumber}» випадає з гоблінів-різьбярів. Інші частини: «{item:Enchanted Silver Ingot}» («{zone:Shadowfang Keep}») і «{item:Purified Kor Gem}» («{zone:Blackfathom Deeps}»).",
  ["f1962ae0"] = "Версія для Орди. Коли здасте його НІП «{npc:Da'grosh}», відкриється наступне завдання.",
  ["f1cfa740"] = "Якщо хочете допомогти НІП «{npc:Eldrun Stormbreaker}» у місті «{zone:Ironforge}», принесіть йому предмети «{item:Azerothian Diamond}» і «{item:Pristine Black Diamond}».",
  ["f1dc94e3"] = "Це завдання виконується поза підземеллям.",
  ["f1f7cd60"] = "Здолайте 8 шукальних залишків, 8 насичених залишків і 8 відлунь мани у підземеллі «{zone:City of Dalaran}» для НІП «{npc:Archmage Modera}» біля міста «{zone:Dalaran}».",
  ["f208c4db"] = "Викривлені тотеми випадають, лише поки це завдання є в журналі. Вода: мурлоки з племені Багноплавців, північно-східне узбережжя локації «{zone:Dustwallow Marsh}». Повітря: кентаври з племені Мародінів, «{zone:Desolace}». Земля: Загублені, «{zone:Swamp of Sorrows}». Вогонь: огри з клану Пилоригачів і троги з Кам’яного Сховища, «{zone:Badlands}».",
  ["f23278cc"] = "Класове завдання воїна з 20-го рівня. У цьому підземеллі: для завдання «{quest:Fire Hardened Mail}» потрібен предмет «{item:Vial of Phlogiston}» від «{npc:Roogug}», першого боса. Після завдання «{quest:Fire Hardened Mail}» НІП «{npc:Grimand Elmore}» («{zone:Stormwind}»), «{npc:Klockmort Spannerspan}» («{zone:Ironforge}») і ще один НІП («{zone:Darnassus}») виготовляють ще по одній частині:",
  ["f261c311"] = "Принесіть предмет «{item:Remote Detonator Kit}» назад до НІП «{npc:Sprite Jumpsprocket}» у районі «{zone:Dwarven District}».",
  ["f38ba4cc"] = "Поверніться з готовою вибухівкою до НІП «{npc:Alba Fairmoon}» у корчму місцевості «{zone:Sentinel Hill}», «{zone:Westfall}».",
  ["f3c6e9b2"] = "Поговоріть з НІП «{npc:Nara Wildmane}» у місцевості «{zone:Elder Rise}» у місті «{zone:Thunder Bluff}».",
  ["f3c74149"] = "Зберіть «{item:Ogre Warbeads}»: 25 шт. з огрів у підземеллі «{zone:Dire Maul}» або «{zone:Blackrock Spire}».",
  ["f42ff3f9"] = "Покажіть НІП «{npc:Cyrus Therepentous}» предмет «{item:Black Dragonflight Molt}», який ви отримали від НІП «{npc:Velarok Windblade}».",
  ["f4956e87"] = "Зберіть «{item:Shadowshard Fragment}»: 10 шт. у підземеллі «{zone:Maraudon}» і віднесіть їх до НІП «{npc:Archmage Tervosh}» у Тераморі на узбережжі локації «{zone:Dustwallow Marsh}».",
  ["f4c9f1c3"] = "Крок у підземеллі «{zone:Razorfen Kraul}». Попереднє завдання (від НІП «{npc:Eldrun Stormbreaker}» у місті «{zone:Ironforge}») відправляє вас до цього НІП. Шамани Альянсу можуть ділитися цим завданням.",
  ["f4def4c0"] = "Спершу потрібні обидва завдання «{zone:KILL ON SIGHT}» і супровід НІП «{npc:Grark Lorkrub}».",
  ["f5004a9a"] = "Проникніть у підземелля «{zone:Krol'dok Stronghold}» і поверніться до того, хто видав завдання, із доказом загибелі їхнього ватажка.",
  ["f53ba3c0"] = "Убийте боса «{npc:Fineous Darkvire}» і заберіть великий молот «{item:Ironfel}». Віднесіть предмет «{item:Ironfel}» до місцевості «{zone:Shrine of Thaurissan}» і покладіть його на статую НІП «{npc:Franclorn Forgewright}».",
  ["f54328d6"] = "Завдання чорнокнижника на скакуна жаху. Використайте предмет із завдання в алхімічній лабораторії в кімнаті боса «{npc:Ras Frostwhisper}» і дочекайтеся пергаменту.",
  ["f5b1710e"] = "Пов’язане вступне завдання: «{quest:Dragonmaw Rumors}». Предмет «{item:Dragonmaw Dispatch}» забирають у сил Драконячої Пащі в підземеллі.",
  ["f610ec2f"] = "Принесіть до НІП «{npc:Mayena Earthseeker}» предмети «{item:Moist Crystal}», «{item:Charged Crystal}», «{item:Noxious Crystal}» і «{item:Fiery Crystal}» з підземелля «{zone:Shaper's Terrace}».",
  ["f62721fb"] = "На 45-му рівні, коли всі доручення виконано, вирушайте до столиці: лист від НІП «{npc:Fahrad}» у поштовій скриньці відправить вас до місцевості «{zone:Ravenholdt Manor}». Прийміть завдання, ще раз поговоріть з НІП «{npc:Fahrad}» і здайте його йому.",
  ["f63a679a"] = "Увійдіть до підземелля «{zone:Alcaz Prison}», убийте 15 солдатів і 8 чарівниць Страшазів та принесіть голову їхньої ватажки тому, хто дав вам це завдання.",
  ["f656cef6"] = "Знайдіть «{zone:Altar of Hakkar}» у підземеллі «{zone:Sunken Temple}» у локації «{zone:Swamp of Sorrows}».",
  ["f67e395c"] = "Принесіть 1 предмет «{item:Jeering Spectre's Essence}», «{item:Dark Rune}»: 4 шт. і «{item:Large Brilliant Shard}»: 8 шт. до НІП «{npc:Falrin Treeshaper}» у підземеллі «{zone:Dire Maul}».",
  ["f6d8af64"] = "Віднесіть «{item:Seal of Ravenholdt}» до НІП «{npc:Fahrad}» у місцевості «{zone:Ravenholdt Manor}», захованій у пагорбах «{zone:Hillsbrad}».",
  ["f713d2f4"] = "Запаліть статуї по колу в правильному порядку, щоб викликати НІП «{npc:Atal'alarion}».",
  ["f74b8fe6"] = "Збирається по всьому Монастирю: з будь-якого багряного гуманоїда на шляху до Собору може випасти потрібний предмет.",
  ["f78f2485"] = "Здобудьте предмет «{item:Mana Sieve}» у храмі в місцевості «{zone:Shen'dralas}» і зберіть ним кристали мани, потім зарядіть пілони й поверніться до НІП «{npc:Mordent Evenshade}».",
  ["f84f688d"] = "Здобудьте предмет «{item:Ancient Gurubashi Idol}» у підземеллі «{zone:The Drowned City}».",
  ["f895f250"] = "Принесіть частини тотема духу до НІП «{npc:Bath'rah the Windwatcher}».",
  ["f8a8c2eb"] = "Знайдіть предмет «{item:Legacy of the Aspects}» і віднесіть його до НІП «{npc:Braug Dimspirit}» біля входу до проходу у локації «{zone:Stonetalon Mountains}».",
  ["f90b7212"] = "Назір видає його ще до того, як ви здасте попереднє завдання.",
  ["f93aac54"] = "Потрібне перед завданням «{quest:The Crone of the Kraul}».",
  ["f99a3bb7"] = "Знайдіть НІП «{npc:Baelog}» у підземеллі «{zone:Uldaman}».",
  ["f9bdd23b"] = "Доставте голову ворога НІП «{npc:Tran'gul}» у місцевості «{zone:Rog'mar}».",
  ["f9c12de9"] = "Принесіть «{item:Glittering Dust}»: 10 шт. до НІП «{npc:Archmage Xylem}».",
  ["fa5abda0"] = "Класове завдання шамана з 30-го рівня; відкривається попереднім завданням шамана (завдання з предметом «{item:Air Totem}»). У цьому підземеллі: «{quest:Elemental Aid}». Убийте боса «{npc:Charlga Razorflank}» і заберіть предмет «{item:Tattered Note}»; його отримує кожен шаман із цим завданням. Далі: 20 викривлених тотемів із чотирьох локацій і елітний ритуал у локації «{zone:Thousand Needles}». Хто з НІП Орди видає завдання після підземелля, ще не підтверджено («{npc:Prate Cloudseer}» або «{npc:Rau Cliffrunner}»): дивіться журнал завдань.",
  ["fae3ab71"] = "Предмет «{item:Dark Iron Map}» починає це завдання і веде прямо до завдання «{quest:Old Ironforge Incursion}».",
  ["fb33a03a"] = "Прочитайте отримані настанови. Потім здобудьте предмет «{item:Amulet of Union}» у підземеллі «{zone:Maraudon}» і поверніть його до НІП «{npc:Centaur Pariah}» на півдні локації «{zone:Desolace}».",
  ["fb8e508a"] = "Остання підготовка перед завданням «{quest:Destruction in Deadmines}».",
  ["fbf6278e"] = "Принесіть шматок скверноткані до НІП «{npc:Impsy}» у локації «{zone:Felwood}».",
  ["fc31e3c1"] = "Убийте «{npc:Plagued Hatchling}»: 20. Після здачі цього завдання з дитинчат можуть випадати предмети: їх можна знову й знову здавати цьому НІП.",
  ["fcba1076"] = "Принесіть предмет «{item:Ambassador Malcin's Head}» до НІП «{npc:Varimathras}» у місті «{zone:Undercity}».",
  ["fce75809"] = "Знайдіть у глибинах підземелля «{zone:Uldaman}» підказку, де шукати самоцвіти.",
  ["fcf5d914"] = "Поверніться з доповіддю до НІП «{npc:Krom'rosh}» у місцевості «{zone:Rog'mar}».",
  ["fd299527"] = "Здолайте боса «{npc:Celebras the Cursed}» там, де сходяться шляхи, і здайте завдання «{quest:Legends of Maraudon}» НІП «{npc:Celebras the Redeemed}», потім допоможіть із ритуалом і знову поговоріть із ним, щоб отримати скіпетр.",
  ["fd4f34ea"] = "Поговоріть з НІП «{npc:Thun'grim Firegaze}» у локації «{zone:The Barrens}».",
  ["fdbf3670"] = "Знайдіть НІП «{npc:Prospector Ryedol}» і повідомте йому, що НІП «{npc:Hammertoe Grez}» живий.",
  ["fddfaca7"] = "Вирушайте до місцевості «{zone:Northdale}» у північно-східній частині «{zone:Eastern Plaguelands}» і здобудьте предмет «{item:Symbol of Lost Honor}». Виконавши це, поверніться до НІП «{npc:Tirion Fordring}».",
  ["fdee0ff9"] = "Виконується разом із завданням «{quest:A Message in Blood}». Після здачі НІП «{npc:Krom'rosh}» видає завдання «{quest:Show Them How It's Done}».",
  ["fe530cd0"] = "Якщо маєте віру, стрибніть із дощок над локацією «{zone:Thousand Needles}».",
  ["fe7a8ff0"] = "Вирушайте до локації «{zone:Silithus}» і пошукайте предмет «{item:Reliquary of Purity}» серед руїн місцевості «{zone:Southwind Village}». Якщо знайдете його, повертайтеся з ним до НІП «{npc:Rabine Saturna}» у місцевості «{zone:Nighthaven}» (локація «{zone:Moonglade}»).",
  ["feaa7f63"] = "Убийте босів «{npc:Bazzalan}» і «{npc:Jergosh the Invoker}» у підземеллі «{zone:Ragefire Chasm}».",
  ["fedaedea"] = "Принесіть потрібну траву: 4 шт., «{item:Giant Silver Vein}»: 10 шт. і предмет «{item:Nagmara's Filled Vial}» до НІП «{npc:Mistress Nagmara}» у підземеллі «{zone:Blackrock Depths}».",
  ["fef59fbe"] = "Поговоріть із НІП «{npc:Grimand Elmore}» у кварталі «{zone:Dwarven District}» міста «{zone:Stormwind}».",
  ["fffd86d2"] = "Покажіть предмет «{item:Document Box}» НІП «{npc:Renzik \"The Shiv\"}».",
}
